import type { BankQuestion } from "@/lib/bank";

/** President, Vice-President, PM and Council of Ministers (Indian Polity): 223 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id": "polity-president-pm-1", "question": "Which Article of the Constitution states that there shall be a President of India?", "options": ["Article 52", "Article 54", "Article 53", "Article 61"], "answer": 0, "explanation": "Article 52 creates the office of the President. Article 53 vests the executive power of the Union in the President, Article 54 covers the electoral college, and Article 61 covers impeachment.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL"},
  {"id": "polity-president-pm-2", "question": "What is the minimum age to be elected President of India?", "options": ["40 years", "30 years", "25 years", "35 years"], "answer": 3, "explanation": "Article 58 requires a presidential candidate to have completed 35 years of age. 25 is the minimum for the Lok Sabha and 30 for the Rajya Sabha.", "difficulty": "easy", "source": "SSC CGL · RRB NTPC · State PSCs"},
  {"id": "polity-president-pm-3", "question": "The Vice-President of India is the ex officio Chairman of the:", "options": ["Lok Sabha", "Rajya Sabha", "NITI Aayog", "Inter-State Council"], "answer": 1, "explanation": "Article 64 makes the Vice-President the ex officio Chairman of the Council of States, that is the Rajya Sabha. The Lok Sabha is presided over by its Speaker.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL"},
  {"id": "polity-president-pm-4", "question": "Under Article 75(1), the Prime Minister is appointed by the:", "options": ["President", "Lok Sabha by vote", "Chief Justice of India", "Speaker of the Lok Sabha"], "answer": 0, "explanation": "Article 75(1) says the Prime Minister is appointed by the President. By convention the President appoints the leader of the majority party or coalition in the Lok Sabha.", "difficulty": "easy", "source": "SSC CGL · RRB NTPC · State PSCs"},
  {"id": "polity-president-pm-5", "question": "Which of these does NOT take part in electing the President of India?", "options": ["Nominated members of the Rajya Sabha", "Elected members of the Lok Sabha", "Elected members of the Rajya Sabha", "Elected members of the Puducherry Legislative Assembly"], "answer": 0, "explanation": "Under Article 54 only elected members vote: elected MPs of both Houses and elected MLAs of the States, Delhi and Puducherry. Nominated members of either House have no vote in this election, although they do vote in impeachment.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "polity-president-pm-6", "question": "The President's power to issue ordinances comes from:", "options": ["Article 123", "Article 213", "Article 356", "Article 72"], "answer": 0, "explanation": "Article 123 empowers the President to promulgate ordinances when Parliament is not in session. Article 213 is the Governor's ordinance power, and Article 72 is the pardoning power.", "difficulty": "moderate", "source": "SSC CGL · RRB NTPC · State PSCs"},
  {"id": "polity-president-pm-7", "question": "The President's power to grant pardons, reprieves, respites and remissions is in:", "options": ["Article 161", "Article 72", "Article 74", "Article 143"], "answer": 1, "explanation": "Article 72 covers the President's pardoning power. Article 161 is the Governor's matching power, which is narrower.", "difficulty": "moderate", "source": "SSC CGL · RRB NTPC · State PSCs"},
  {"id": "polity-president-pm-8", "question": "If the President wants to resign, the letter of resignation is addressed to the:", "options": ["Vice-President", "Chief Justice of India", "Speaker of the Lok Sabha", "Prime Minister"], "answer": 0, "explanation": "Article 56(1)(a) says the President may resign by writing under his hand addressed to the Vice-President. The Chief Justice only administers the oath.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "polity-president-pm-9", "question": "The Vice-President is elected by an electoral college made up of:", "options": ["Elected members of the Lok Sabha only", "Elected members of both Houses of Parliament and the State Assemblies", "Members of the Rajya Sabha only", "All members (elected and nominated) of both Houses of Parliament"], "answer": 3, "explanation": "Under Article 66, the electoral college for the Vice-President is all members of both Houses of Parliament, nominated members included. State legislators have no part in this election, unlike the presidential election.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL · UPSC Prelims"},
  {"id": "polity-president-pm-10", "question": "The total number of ministers, including the Prime Minister, in the Union Council of Ministers cannot exceed:", "options": ["20% of the total members of the Lok Sabha", "15% of the total members of both Houses", "15% of the total members of the Lok Sabha", "10% of the total members of the Lok Sabha"], "answer": 2, "explanation": "Article 75(1A), added by the 91st Amendment (2003), caps the Council of Ministers at 15% of the total membership of the Lok Sabha. The base is the Lok Sabha only, not both Houses.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL · State PSCs"},
  {"id": "polity-president-pm-11", "question": "The Union Council of Ministers is collectively responsible to the:", "options": ["Rajya Sabha", "Lok Sabha", "President", "Parliament as a whole"], "answer": 1, "explanation": "Article 75(3) makes the Council of Ministers collectively responsible to the House of the People (Lok Sabha). Ministers hold office during the President's pleasure (Article 75(2)), but collective responsibility is owed only to the Lok Sabha.", "difficulty": "moderate", "source": "SSC CGL · RRB NTPC · State PSCs"},
  {"id": "polity-president-pm-12", "question": "On which ground can the President be impeached under Article 61?", "options": ["Incapacity", "Loss of confidence of the Lok Sabha", "Proved misbehaviour", "Violation of the Constitution"], "answer": 3, "explanation": "The only ground under Article 61 is “violation of the Constitution”. “Proved misbehaviour or incapacity” is the ground for removing judges of the Supreme Court and High Courts.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL · UPSC Prelims"},
  {"id": "polity-president-pm-13", "question": "What is the longest an ordinance can stay in force without Parliament approving it?", "options": ["Six months", "One year", "Six weeks", "Six months and six weeks"], "answer": 3, "explanation": "An ordinance lapses six weeks after Parliament reassembles, and the gap between two sessions can be up to six months. So the longest possible life without approval is about six months and six weeks.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL · UPSC Prelims"},
  {"id": "polity-president-pm-14", "question": "The Indian President can use a “pocket veto” because:", "options": ["A bill lapses automatically if not signed within 14 days", "Article 111 lets the President reject any bill outright", "The Rajya Sabha can ask the President to hold back a bill", "The Constitution sets no time limit for the President to act on an ordinary bill"], "answer": 3, "explanation": "Article 111 sets no time limit for assent to an ordinary bill. The President can therefore simply keep a bill pending, as President Zail Singh did with the Indian Post Office (Amendment) Bill in 1986.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "polity-president-pm-15", "question": "Which of these bills can the President NOT return to Parliament for reconsideration?", "options": ["A private member's bill passed by both Houses", "An ordinary bill passed by both Houses", "A Money Bill", "A bill passed at a joint sitting"], "answer": 2, "explanation": "Under Article 111 the President may return any bill except a Money Bill. A bill passed at a joint sitting is still an ordinary bill and can be returned. (A Constitution Amendment Bill also cannot be returned, because the 24th Amendment made assent compulsory.)", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "polity-president-pm-16", "question": "Which of these can the President do that a Governor can NOT do?", "options": ["Commute a death sentence", "Grant a reprieve", "Remit a sentence for an offence under a State law", "Pardon a death sentence"], "answer": 3, "explanation": "Article 72 lets the President pardon a death sentence. Under Article 161 a Governor can suspend, remit or commute a death sentence but cannot fully pardon it. The Governor also has no power over court-martial sentences.", "difficulty": "hard", "source": "UPSC Prelims · State PSCs"},
  {"id": "polity-president-pm-17", "question": "Who administers the oath of office to the Vice-President of India?", "options": ["Chief Justice of India", "President", "Senior-most member of the Rajya Sabha", "Speaker of the Lok Sabha"], "answer": 1, "explanation": "Article 69 says the Vice-President takes the oath before the President or a person the President appoints. The Chief Justice administers the oath to the President (Article 60), which is why that option is the common trap.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL · UPSC Prelims"},
  {"id": "polity-president-pm-18", "question": "If the office of President falls vacant through death, the election to fill it must be held within:", "options": ["One year", "Six months", "One month", "Three months"], "answer": 1, "explanation": "Article 62(2) says such a vacancy must be filled by an election held as soon as possible, and in no case later than six months from the date the vacancy occurs. The new President serves a full five-year term.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "polity-president-pm-19", "question": "A resolution to remove the Vice-President can be moved first only in the:", "options": ["A joint sitting of both Houses", "Rajya Sabha", "Either House", "Lok Sabha"], "answer": 1, "explanation": "Article 67(b): the resolution is passed in the Rajya Sabha by a majority of all its then members and agreed to by the Lok Sabha, after at least 14 days' notice. It cannot start in the Lok Sabha.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "polity-president-pm-20", "question": "If the offices of both the President and the Vice-President fall vacant together, who discharges the functions of the President?", "options": ["Speaker of the Lok Sabha", "Deputy Chairman of the Rajya Sabha", "Chief Justice of India", "Prime Minister"], "answer": 2, "explanation": "Under the President (Discharge of Functions) Act, 1969, the Chief Justice of India acts, or failing them the senior-most available Supreme Court judge. Justice M. Hidayatullah did so in 1969.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL · State PSCs"},
  {"id": "polity-president-pm-21", "question": "For the value of an MLA's vote in the presidential election, the population of a State is currently taken from the:", "options": ["1951 Census", "1971 Census", "Latest Census", "2001 Census"], "answer": 1, "explanation": "The 84th Amendment (2001) froze the population base at the 1971 Census until the figures of the first Census taken after 2026 are published. Using the latest Census is the trap.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "polity-president-pm-22", "question": "Which Amendment let the President send the advice of the Council of Ministers back once for reconsideration, while staying bound by the advice given after that?", "options": ["52nd Amendment", "42nd Amendment", "44th Amendment", "61st Amendment"], "answer": 2, "explanation": "The 42nd Amendment (1976) made the advice binding. The 44th Amendment (1978) added the proviso to Article 74(1) allowing the President to ask once for reconsideration, after which the advice is binding.", "difficulty": "hard", "source": "UPSC Prelims · State PSCs"},
  {"id": "polity-president-pm-23", "question": "The Prime Minister's duty to give the President information about the administration of the Union and proposals for legislation is in:", "options": ["Article 77", "Article 74", "Article 78", "Article 75"], "answer": 2, "explanation": "Article 78 sets out the Prime Minister's duty to communicate decisions of the Council of Ministers and give information the President asks for. Article 77 deals with how Government business is conducted.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "polity-president-pm-24", "question": "A person who is not a Member of Parliament is appointed a Union minister. What happens if they do not become a member within six consecutive months?", "options": ["They can continue if the Prime Minister certifies it", "They become a member of the Rajya Sabha automatically", "The appointment needs approval by the Lok Sabha", "They cease to be a minister at the end of that period"], "answer": 3, "explanation": "Article 75(5) says a minister who is not a member of either House for six consecutive months ceases to be a minister at the end of that period. The same rule covers the Prime Minister.", "difficulty": "hard", "source": "SSC CGL · RRB NTPC · State PSCs"},
  {"id": "polity-president-pm-25", "question": "How many of these statements are correct? I. The President holds office for five years from the date he enters office. II. A person who has been President can be re-elected any number of times. III. The impeachment charge against the President can be started in either House of Parliament. IV. Nominated members of Parliament take part in impeachment though they cannot vote in the presidential election.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are correct. Article 56 sets the five-year term. Article 57 allows re-election with no limit. Article 61 lets either House bring the charge, and nominated members vote in impeachment but not in the election.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-president-pm-26", "question": "How many of these statements about the Vice-President are correct? I. They must be qualified for election as a member of the Rajya Sabha. II. They must have completed 35 years of age. III. Disputes about their election are decided by the Election Commission. IV. They draw a separate salary fixed by the Constitution for the office of Vice-President.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "Only I and II are correct (Article 66(3)). Disputes go to the Supreme Court under Article 71, not the Election Commission. There is no salary for the office of Vice-President as such; they are paid as Chairman of the Rajya Sabha.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-president-pm-27", "question": "Assertion (A): The President cannot promulgate an ordinance while both Houses of Parliament are in session. Reason (R): An ordinance can be issued only when both Houses of Parliament are in recess.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 2, "explanation": "A is true: Article 123 allows ordinances “except when both Houses of Parliament are in session”. R is false, because an ordinance can also be issued when only one House is in session.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-president-pm-28", "question": "Match List I (Article) with List II (Subject): A. Article 56 B. Article 61 C. Article 72 D. Article 76 — 1. Attorney General for India 2. Pardoning power 3. Term of office of the President 4. Procedure for impeachment of the President", "options": ["A-3, B-4, C-1, D-2", "A-4, B-3, C-2, D-1", "A-2, B-4, C-3, D-1", "A-3, B-4, C-2, D-1"], "answer": 3, "explanation": "Article 56 sets the term of office, Article 61 the impeachment procedure, Article 72 the pardoning power, and Article 76 the Attorney General.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSCs"},
  {"id": "polity-president-pm-29", "question": "Which pair of a form of clemency and its meaning is NOT correctly matched?", "options": ["Remission — the period of the sentence is cut without changing its character", "Respite — a lighter sentence because of a special fact such as pregnancy", "Reprieve — a permanent cut in the amount of the sentence", "Commutation — a lighter form of punishment in place of a harsher one"], "answer": 2, "explanation": "A reprieve is a temporary stay of a sentence, especially a death sentence, while a pardon or commutation is sought. Cutting the length of the sentence is remission. The other three pairs are correct.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-president-pm-30", "question": "How many of these statements about the President's pardoning power are correct? I. The President exercises it on the advice of the Council of Ministers. II. Its exercise is wholly outside judicial review. III. A person seeking mercy has no right to an oral hearing before the President.", "options": ["Only one", "Only two", "All three", "None"], "answer": 1, "explanation": "I and III are correct: Maru Ram (1980) held the power is exercised on ministerial advice, and Kehar Singh (1989) held there is no right to an oral hearing. II is wrong: Epuru Sudhakar (2006) allowed limited judicial review, for example of arbitrary or mala fide decisions.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-president-pm-31", "question": "How many of these statements about ordinances under Article 123 are correct? I. An ordinance can amend a tax law. II. An ordinance can amend the Constitution. III. Re-promulgating ordinances again and again without placing them before Parliament is a fraud on the Constitution. IV. The 38th Amendment made the President's satisfaction final, and the 44th Amendment removed that immunity.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, III and IV are correct. An ordinance has the same force as an Act of Parliament but cannot amend the Constitution, because an amendment needs Article 368. Krishna Kumar Singh (2017) condemned repeated re-promulgation, and the 44th Amendment undid the 38th Amendment's immunity clause.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-president-pm-32", "question": "Assertion (A): The whole Council of Ministers must resign if the Lok Sabha passes a no-confidence motion against it. Reason (R): Article 75(3) makes the Council of Ministers collectively responsible to the House of the People.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Both are true, and R explains A. Collective responsibility to the Lok Sabha means the Ministry stands or falls together, so losing the Lok Sabha's confidence forces all ministers out.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-president-pm-33", "question": "How many of these statements are correct? I. The Prime Minister must be a member of the Lok Sabha. II. A person who is not a member of either House can be appointed Prime Minister for up to six months. III. The Constitution gives the Prime Minister a fixed five-year term. IV. The Lok Sabha can remove an individual minister by passing a no-confidence motion against that minister alone.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 0, "explanation": "Only II is correct (Article 75(5)). The Prime Minister can come from the Rajya Sabha, as Indira Gandhi (1966) and Manmohan Singh did. Ministers hold office during the President's pleasure with no fixed term. A no-confidence motion targets the whole Council, and an individual minister answers to the Prime Minister and the President.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-president-pm-34", "question": "Arrange these Presidents in the order they held office: 1. K. R. Narayanan 2. Zakir Husain 3. Giani Zail Singh 4. V. V. Giri", "options": ["2, 4, 1, 3", "2, 3, 4, 1", "2, 4, 3, 1", "4, 2, 3, 1"], "answer": 2, "explanation": "Zakir Husain (1967–69), V. V. Giri (1969–74), Giani Zail Singh (1982–87) and K. R. Narayanan (1997–2002). V. V. Giri was acting President after Zakir Husain died in 1969 and was then elected President himself.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSCs"},
  {"id": "polity-president-pm-35", "question": "Which pair of an Article on the Union executive and its subject is NOT correctly matched?", "options": ["Article 75(3) — Collective responsibility to the House of the People", "Article 74 — Council of Ministers to aid and advise the President", "Article 77 — Duties of the Prime Minister to furnish information to the President", "Article 53 — Executive power of the Union vested in the President"], "answer": 2, "explanation": "Article 77 deals with how the Government of India conducts its business: executive action is taken in the President's name, and the President makes the rules for allocating work among ministers. The Prime Minister's duty to inform the President is Article 78.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-president-pm-36", "question": "How many of these statements about the presidential election are correct? I. Elected members of State Legislative Councils vote in it. II. Elected members of the Legislative Assemblies of Delhi and Puducherry vote in it. III. It is held by proportional representation using the single transferable vote, by secret ballot. IV. It is conducted by the Election Commission of India.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "II, III and IV are correct. Delhi and Puducherry were added by the 70th Amendment (1992), Article 55(3) sets the voting method, and Article 324 puts the election under the Election Commission. Legislative Council members have no vote.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-president-pm-37", "question": "In a presidential election, a State's population (1971 Census) is 50,00,000 and its Assembly has 100 elected members. What is the value of each MLA's vote?", "options": ["5", "50", "500", "5,000"], "answer": 1, "explanation": "Value = population ÷ elected MLAs ÷ 1,000 = 50,00,000 ÷ 100 = 50,000, and 50,000 ÷ 1,000 = 50. Leaving out the division by 1,000 gives 50,000; dividing the wrong way gives the other options.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-president-pm-38", "question": "How many of these are correct about the impeachment of the President? I. The notice of the charge must be signed by at least one-fourth of the total members of the House. II. At least 14 days' written notice must be given. III. The resolution must be passed by two-thirds of the total membership of the House. IV. Nominated members of both Houses take part in the process.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are correct under Article 61. Elected members of the State Assemblies, who vote in the election, take no part in impeachment. No President has been impeached so far.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-president-pm-39", "question": "Assertion (A): The President can be impeached only for “violation of the Constitution”. Reason (R): The impeachment resolution must be passed by a majority of two-thirds of the total membership of each House.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 1, "explanation": "Both are true under Article 61, but R describes the majority needed, not why the ground is limited. So R does not explain A.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-president-pm-40", "question": "How many of these statements are correct? I. While acting as President, the Vice-President does not perform the duties of Chairman of the Rajya Sabha. II. The Vice-President is removed by the same formal impeachment process as the President. III. The Vice-President continues in office after the five-year term until a successor enters office. IV. While acting as President, the Vice-President gets the emoluments of the President.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I (Article 64 proviso), III (Article 67(c)) and IV (Article 65(3)) are correct. II is wrong: the Vice-President is removed by a Rajya Sabha resolution agreed to by the Lok Sabha, with no impeachment and no stated grounds.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-president-pm-41", "question": "Which Article of the Constitution states that there shall be a Vice-President of India?", "options": ["Article 52", "Article 63", "Article 64", "Article 66"], "answer": 1, "explanation": "Article 63 creates the office of Vice-President. Article 52 is the President, Article 64 makes the Vice-President ex officio Chairman of the Rajya Sabha, and Article 66 deals with the Vice-President's election.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL"},
  {"id": "polity-president-pm-42", "question": "Who administers the oath of office to the President of India?", "options": ["The Vice-President", "The Speaker of the Lok Sabha", "The Chief Justice of India", "The Prime Minister"], "answer": 2, "explanation": "Under Article 60 the oath is administered by the Chief Justice of India or, in his absence, the senior-most available judge of the Supreme Court.", "difficulty": "easy", "source": "RRB NTPC · SSC CGL"},
  {"id": "polity-president-pm-43", "question": "What is the minimum age for election as Vice-President of India?", "options": ["25 years", "30 years", "35 years", "40 years"], "answer": 2, "explanation": "Article 66(3) requires the Vice-President to be at least 35 years old, the same as the President, and qualified for election to the Rajya Sabha.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL"},
  {"id": "polity-president-pm-44", "question": "Under Article 53, the executive power of the Union is vested in the:", "options": ["Prime Minister", "Union Cabinet", "President", "Parliament"], "answer": 2, "explanation": "Article 53(1) vests the executive power of the Union in the President, to be exercised directly or through subordinate officers; the Prime Minister and Cabinet are the real executive by convention.", "difficulty": "easy", "source": "RRB NTPC · SSC CGL"},
  {"id": "polity-president-pm-45", "question": "The supreme command of the Defence Forces of the Union is vested in the:", "options": ["Chief of Defence Staff", "Defence Minister", "Prime Minister", "President"], "answer": 3, "explanation": "Article 53(2) vests the supreme command of the Defence Forces in the President, its exercise regulated by law.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL"},
  {"id": "polity-president-pm-46", "question": "Under Article 57, a person who holds or has held the office of President is:", "options": ["Not eligible for a second term", "Eligible for re-election, with no limit in the Constitution on the number of terms", "Eligible for only one more term", "Eligible for re-election only after a gap of five years"], "answer": 1, "explanation": "Article 57 makes a President eligible for re-election and sets no limit. The two-term bar is in the US Constitution, not India's; Rajendra Prasad was elected twice.", "difficulty": "moderate", "source": "UPSC Prelims · SSC CGL · State PSC"},
  {"id": "polity-president-pm-47", "question": "Doubts and disputes arising out of the election of the President are decided by the:", "options": ["Election Commission", "Parliament", "Supreme Court", "Chief Justice of India alone"], "answer": 2, "explanation": "Article 71(1) says such disputes are inquired into and decided by the Supreme Court, whose decision is final. The Election Commission only conducts the election.", "difficulty": "moderate", "source": "UPSC Prelims · SSC CGL · State PSC"},
  {"id": "polity-president-pm-48", "question": "When the Vice-President acts as President, he draws the salary and allowances of the:", "options": ["Chairman of the Rajya Sabha", "President", "Vice-President plus a special allowance", "Chief Justice of India"], "answer": 1, "explanation": "Under Article 65(3), while acting as or discharging the functions of President, the Vice-President has all the powers, immunities and emoluments of the President, and does not draw his Chairman's salary for that period.", "difficulty": "moderate", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-president-pm-49", "question": "Since the 104th Amendment (2020), the President's power to nominate members to Parliament covers:", "options": ["12 members of the Rajya Sabha only", "12 members of the Rajya Sabha and 2 Anglo-Indians to the Lok Sabha", "2 Anglo-Indians to the Lok Sabha only", "10 members of the Rajya Sabha"], "answer": 0, "explanation": "The 104th Amendment did not extend Anglo-Indian nomination to the Lok Sabha (Article 331) beyond January 2020, so only the Article 80 nomination of 12 Rajya Sabha members (literature, science, art, social service) remains.", "difficulty": "moderate", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-president-pm-50", "question": "Which Article provides that there shall be a Council of Ministers with the Prime Minister at the head to aid and advise the President?", "options": ["Article 72", "Article 74", "Article 75", "Article 77"], "answer": 1, "explanation": "Article 74(1) creates the Council of Ministers headed by the PM. Article 75 covers appointment, tenure and responsibility of ministers; Article 77 covers the conduct of business of the Government of India.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "polity-president-pm-51", "question": "The emoluments and allowances of the President are:", "options": ["Voted annually by the Lok Sabha", "Charged on the Consolidated Fund of India and cannot be reduced during the term", "Fixed by the Union Cabinet", "Paid from the Contingency Fund of India"], "answer": 1, "explanation": "Under Articles 59(4) and 112(3), the President's emoluments are charged expenditure (not voted) and cannot be diminished during his term of office.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "polity-president-pm-52", "question": "Rules for the more convenient transaction of the business of the Government of India and for allocating that business among ministers are made by the:", "options": ["Prime Minister", "Cabinet Secretary", "Parliament", "President"], "answer": 3, "explanation": "Article 77(3) empowers the President to make these rules (the Allocation of Business Rules and Transaction of Business Rules), though in practice on the advice of the PM.", "difficulty": "moderate", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-president-pm-53", "question": "The idea of collective responsibility of the Council of Ministers to the lower House was borrowed from the Constitution of:", "options": ["the USA", "Canada", "the United Kingdom", "Ireland"], "answer": 2, "explanation": "Parliamentary government with ministerial (collective) responsibility comes from the British system; the USA has a presidential system without it.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "polity-president-pm-54", "question": "The President's special address to both Houses at the start of the first session after each general election and of the first session each year is provided under:", "options": ["Article 85", "Article 86", "Article 87", "Article 88"], "answer": 2, "explanation": "Article 87 provides for this special address. Article 86 is the President's general right to address or send messages to the Houses, and Article 85 deals with summoning and prorogation.", "difficulty": "moderate", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-president-pm-55", "question": "The word ‘Cabinet’ appears in the Constitution of India in only one Article, inserted by the 44th Amendment (1978). Which one?", "options": ["Article 74", "Article 75", "Article 352", "Article 356"], "answer": 2, "explanation": "Article 352(3) says a National Emergency can be proclaimed only on the written decision of the Union Cabinet (the Prime Minister and Cabinet-rank ministers). Articles 74 and 75 speak only of the ‘Council of Ministers’.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-president-pm-56", "question": "For the purpose of eligibility for election as President (Article 58), which of these is NOT deemed to be an office of profit?", "options": ["Judge of a High Court", "Comptroller and Auditor General", "Governor of a State", "Chairman of the UPSC"], "answer": 2, "explanation": "The Explanation to Article 58 says a person is not deemed to hold an office of profit merely because he is the President, Vice-President, a Governor, or a Union or State minister. The other posts are offices of profit.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-president-pm-57", "question": "Elected members of the Legislative Assemblies of the National Capital Territory of Delhi and the Union Territory of Puducherry became part of the presidential electoral college through the:", "options": ["61st Amendment", "69th Amendment", "70th Amendment", "74th Amendment"], "answer": 2, "explanation": "The 70th Amendment (1992) added an Explanation to Article 54 so that ‘State’ includes Delhi and Puducherry. The 69th Amendment (1991) had created the Delhi Legislative Assembly itself.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-president-pm-58", "question": "An election to fill a vacancy caused by the expiry of the President's term must be completed:", "options": ["Within six months after the term expires", "Before the expiry of the term", "Within one month after the term expires", "Within three months after the term expires"], "answer": 1, "explanation": "Article 62(1) requires the election to be completed before the term expires; Article 56(1)(c) lets the outgoing President continue until the successor enters office. The six-month limit of Article 62(2) applies to vacancies caused by death, resignation or removal.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-president-pm-59", "question": "The form of the oath of office of the President of India is set out in:", "options": ["The Third Schedule", "Article 60 itself", "The Presidential and Vice-Presidential Elections Act, 1952", "The Fourth Schedule"], "answer": 1, "explanation": "The President's oath is written into Article 60 itself (as is the Vice-President's in Article 69). The Third Schedule holds the forms for ministers, MPs, MLAs, judges and the CAG, which is the usual trap.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-president-pm-60", "question": "Under Article 75(1B), a member of either House disqualified for defection cannot be appointed a minister until:", "options": ["Six months have passed", "The end of his term as member, or his re-election, whichever is earlier", "The Speaker revokes the disqualification", "The next session of Parliament begins"], "answer": 1, "explanation": "Article 75(1B), added by the 91st Amendment (2003), bars a defector from ministerial office for the period from disqualification till his term would have expired or till he is elected again, whichever is earlier.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-president-pm-61", "question": "Which Article says that the question whether any advice, and if so what advice, was tendered by ministers to the President shall not be inquired into in any court?", "options": ["Article 74(2)", "Article 75(3)", "Article 77(2)", "Article 78(b)"], "answer": 0, "explanation": "Article 74(2) protects ministerial advice from judicial inquiry. Article 77(2) only deals with the authentication of orders made in the President's name.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-president-pm-62", "question": "Who was the first Prime Minister of India to be defeated on a motion of confidence in the Lok Sabha?", "options": ["Morarji Desai", "Charan Singh", "V. P. Singh", "Atal Bihari Vajpayee"], "answer": 2, "explanation": "V. P. Singh lost a confidence vote on 7 November 1990. Morarji Desai resigned in 1979 before a no-confidence vote could be taken, and Vajpayee's one-vote defeat came later, in 1999.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-president-pm-63", "question": "Which Prime Minister resigned without ever facing the Lok Sabha as Prime Minister?", "options": ["Chandra Shekhar", "Charan Singh", "I. K. Gujral", "Gulzarilal Nanda"], "answer": 1, "explanation": "Charan Singh became PM in July 1979 and resigned in August 1979 before seeking a vote of confidence, so he never faced the Lok Sabha as PM.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "polity-president-pm-64", "question": "When V. V. Giri, acting as President after Zakir Husain's death, resigned in July 1969 to contest the presidential election, who discharged the functions of the President?", "options": ["G. S. Pathak", "Chief Justice M. Hidayatullah", "Speaker N. Sanjiva Reddy", "Prime Minister Indira Gandhi"], "answer": 1, "explanation": "With both offices vacant, the Chief Justice of India, M. Hidayatullah, discharged the President's functions under the President (Discharge of Functions) Act, 1969, until Giri was sworn in.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-president-pm-65", "question": "Under the Presidential and Vice-Presidential Elections Act, 1952 (as amended in 1997), a nomination for the office of President must be subscribed by at least:", "options": ["10 proposers and 10 seconders", "20 proposers and 20 seconders", "50 proposers and 50 seconders", "100 proposers and 100 seconders"], "answer": 2, "explanation": "The 1997 amendment raised the requirement to 50 electors as proposers and 50 as seconders for President, with a deposit of ₹15,000. For Vice-President it is 20 and 20.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-president-pm-66", "question": "The Vice-President of India resigns by writing under his hand addressed to the:", "options": ["Chief Justice of India", "Speaker of the Lok Sabha", "President", "Deputy Chairman of the Rajya Sabha"], "answer": 2, "explanation": "Article 67(a) says the Vice-President resigns by writing addressed to the President. It is the President who writes to the Vice-President (Article 56(1)(a)), the usual trap.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "polity-president-pm-67", "question": "Which of these does NOT cause a vacancy in the office of President?", "options": ["The Supreme Court declaring his election void", "Dissolution of the Lok Sabha", "Resignation addressed to the Vice-President", "Removal by impeachment"], "answer": 1, "explanation": "The President's term is independent of the Lok Sabha. A void election (Article 71), resignation (Article 56(1)(a)) and impeachment (Article 61) all create vacancies; acts done before an election is set aside remain valid.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-president-pm-68", "question": "How many of these statements about the Vice-President are correct? I. Disputes about his election are decided by the Supreme Court. II. He is removed by impeachment on the ground of violation of the Constitution. III. He is not a member of either House of Parliament. IV. His nomination needs at least 20 proposers and 20 seconders.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, III and IV are correct (Articles 71, 66(2) and the 1952 Act). II is wrong: the Vice-President is removed by a Rajya Sabha resolution passed by an effective majority and agreed to by the Lok Sabha (Article 67(b)); no ground is specified and it is not called impeachment.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-president-pm-69", "question": "Assertion (A): Nominated members of Parliament vote in the election of the Vice-President. Reason (R): The electoral college for the Vice-President consists of all members of both Houses of Parliament.", "options": ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is not the correct explanation of A", "A is true, but R is false", "A is false, but R is true"], "answer": 0, "explanation": "Article 66(1) uses ‘members of both Houses’, so nominated MPs vote for the Vice-President, unlike the presidential election where only elected MPs vote. R explains A.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-president-pm-70", "question": "Match List I (Article) with List II (Subject): A. Article 59 B. Article 65 C. Article 71 D. Article 77 — 1. Conduct of business of the Government of India 2. Election disputes of President and Vice-President 3. Vice-President to act as President 4. Conditions of the President's office", "options": ["A-3, B-4, C-2, D-1", "A-2, B-3, C-4, D-1", "A-4, B-3, C-1, D-2", "A-4, B-3, C-2, D-1"], "answer": 3, "explanation": "Article 59 lays down conditions of office (no seat in a legislature, no office of profit), Article 65 lets the Vice-President act as President, Article 71 covers election disputes and Article 77 the conduct of government business.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-president-pm-71", "question": "Arrange these Prime Ministers in the order in which they first took office: 1. Chandra Shekhar 2. Lal Bahadur Shastri 3. H. D. Deve Gowda 4. Morarji Desai", "options": ["2-4-3-1", "2-1-4-3", "2-4-1-3", "4-2-1-3"], "answer": 2, "explanation": "Shastri (1964), Morarji Desai (1977), Chandra Shekhar (1990), Deve Gowda (1996).", "difficulty": "very-hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "polity-president-pm-72", "question": "How many of these statements about the President's veto are correct? I. Since the 24th Amendment, the President must give assent to a Constitution Amendment Bill. II. The pocket veto was used by President Zail Singh on the Indian Post Office (Amendment) Bill, 1986. III. A bill returned under the suspensive veto becomes law if Parliament passes it again by a simple majority, with or without changes. IV. The President can return a Money Bill once for reconsideration.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct. IV is wrong: a Money Bill, introduced with the President's prior recommendation, can only be assented to or withheld, never returned.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-president-pm-73", "question": "Assertion (A): A minister who is a member of the Rajya Sabha can speak in the Lok Sabha. Reason (R): Article 88 gives every minister the right to speak in and take part in the proceedings of either House, but to vote only in the House of which he is a member.", "options": ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is not the correct explanation of A", "A is true, but R is false", "A is false, but R is true"], "answer": 0, "explanation": "Article 88 gives ministers (and the Attorney General) the right to speak in either House and its committees, without a vote outside their own House. R directly explains A.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-president-pm-74", "question": "Which of these officials is appointed by the President but can NOT be removed by the President at pleasure?", "options": ["Attorney General for India", "Governor of a State", "Comptroller and Auditor General", "A Union minister"], "answer": 2, "explanation": "The AG, Governors and ministers hold office during the pleasure of the President. The CAG (Article 148) can be removed only like a Supreme Court judge, on an address by both Houses passed by a special majority.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-president-pm-75", "question": "In a presidential election, the total value of the votes of all elected MLAs is 5,40,000 and Parliament has 776 elected members. What is the value of each MP's vote? (Fractions above one-half count as one.)", "options": ["695", "696", "700", "708"], "answer": 1, "explanation": "Value of an MP's vote = total value of MLAs' votes ÷ elected MPs = 5,40,000 ÷ 776 = 695.88. The fraction 0.88 exceeds one-half, so it rounds up to 696.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-president-pm-76", "question": "How many of these statements are correct? I. The post of Deputy Prime Minister is not mentioned in the Constitution. II. Sardar Patel was the first Deputy Prime Minister. III. A Deputy Prime Minister takes a separate oath set out for that office in the Third Schedule. IV. The Constitution divides the Council of Ministers into Cabinet ministers, ministers of state and deputy ministers.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "I and II are correct. III is wrong: a Deputy PM takes the ordinary oath of a Union minister. IV is wrong: the three ranks are a matter of convention, not the Constitution.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-president-pm-77", "question": "Which of these Vice-Presidents did NOT later become President of India?", "options": ["R. Venkataraman", "Shankar Dayal Sharma", "K. R. Narayanan", "Bhairon Singh Shekhawat"], "answer": 3, "explanation": "Venkataraman, Sharma and Narayanan moved from Vice-President to President. Bhairon Singh Shekhawat (Vice-President 2002–07) lost the 2007 presidential election to Pratibha Patil.", "difficulty": "very-hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "polity-president-pm-78", "question": "Arrange these Vice-Presidents in the order in which they held office: 1. B. D. Jatti 2. Zakir Husain 3. M. Hidayatullah 4. G. S. Pathak", "options": ["4-2-1-3", "2-1-4-3", "2-4-1-3", "2-4-3-1"], "answer": 2, "explanation": "Zakir Husain (1962–67), G. S. Pathak (1969–74), B. D. Jatti (1974–79), M. Hidayatullah (1979–84).", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-president-pm-79", "question": "How many of these statements are correct? I. The President's emoluments cannot be diminished during his term. II. The Vice-President draws his salary as Chairman of the Rajya Sabha, not as Vice-President. III. No criminal proceedings can be started against the President during his term. IV. Civil proceedings for his personal acts can be started during his term after two months' written notice.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are correct: Article 59(4), the Salaries and Allowances of Officers of Parliament Act (no separate salary for the Vice-President), Article 361(2) and Article 361(4).", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-president-pm-80", "question": "Assertion (A): Parliament consists of the President and the two Houses, though the President is not a member of either House. Reason (R): The President has a casting vote at a joint sitting of the two Houses.", "options": ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is not the correct explanation of A", "A is true, but R is false", "A is false, but R is true"], "answer": 2, "explanation": "A is true under Articles 79 and 59(1). R is false: a joint sitting under Article 108 is presided over by the Speaker, who has a casting vote; the President only summons it.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-president-pm-81", "question": "Match the President with a distinctive fact: A. Zakir Husain B. V. V. Giri C. N. Sanjiva Reddy D. Pratibha Patil — 1. Elected unopposed 2. First woman President 3. Elected only after second-preference votes were counted 4. First President to die in office", "options": ["A-4, B-1, C-3, D-2", "A-1, B-3, C-4, D-2", "A-4, B-3, C-1, D-2", "A-3, B-4, C-1, D-2"], "answer": 2, "explanation": "Zakir Husain died in office in 1969; Giri won in 1969 only after second preferences were counted; Sanjiva Reddy was elected unopposed in 1977; Pratibha Patil (2007) was the first woman President.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-president-pm-82", "question": "How many of these are duties of the Prime Minister under Article 78? I. To communicate to the President all decisions of the Council of Ministers on administration and proposals for legislation. II. To furnish information on these matters as the President may call for. III. If the President requires, to submit for the Council's consideration any matter decided by a minister but not considered by the Council. IV. To consult the Chief Justice of India before recommending the appointment of ministers.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "Clauses (a), (b) and (c) of Article 78 match I, II and III. IV is invented: there is no such consultation.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-president-pm-83", "question": "How many of these statements are correct? I. Other Union ministers are appointed by the President on the advice of the Prime Minister. II. A member of the Rajya Sabha can be Prime Minister. III. Indira Gandhi was a member of the Rajya Sabha when she first became Prime Minister in 1966. IV. Manmohan Singh was a member of the Lok Sabha while he was Prime Minister.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I (Article 75(1)), II and III are correct. IV is wrong: Manmohan Singh was a Rajya Sabha member from Assam throughout his time as PM (2004–14).", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-president-pm-84", "question": "Match the case with what it held on the President's clemency power: A. Maru Ram (1980) B. Kehar Singh (1989) C. Epuru Sudhakar (2006) D. Shatrughan Chauhan (2014) — 1. Unexplained delay in deciding a mercy petition can justify commuting a death sentence 2. Clemency decisions are open to limited judicial review 3. The petitioner has no right to an oral hearing 4. The power is exercised on the advice of the Council of Ministers", "options": ["A-4, B-3, C-2, D-1", "A-4, B-2, C-3, D-1", "A-3, B-4, C-2, D-1", "A-4, B-3, C-1, D-2"], "answer": 0, "explanation": "Maru Ram tied the power to ministerial advice; Kehar Singh denied a right to oral hearing; Epuru Sudhakar allowed review on grounds like mala fides or irrelevant considerations; Shatrughan Chauhan treated inordinate delay as a ground for commutation.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-president-pm-85", "question": "The Lok Sabha now has 543 members. Under Article 75(1A), what is the largest possible size of the Union Council of Ministers, including the Prime Minister?", "options": ["80", "81", "82", "85"], "answer": 1, "explanation": "The total cannot exceed 15% of the Lok Sabha's total membership: 15% of 543 = 81.45. Since it must not exceed this figure, the maximum is 81, not 82 (rounding up would cross the limit).", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-president-pm-86", "question": "Who was the first President of India?", "options": ["S. Radhakrishnan", "Rajendra Prasad", "Zakir Husain", "C. Rajagopalachari"], "answer": 1, "explanation": "Rajendra Prasad was President from 1950 to 1962, the only one to serve two full terms. C. Rajagopalachari was the last Governor-General, and Radhakrishnan the first Vice-President.", "difficulty": "easy", "source": "SSC CGL · RRB NTPC"},
  {"id": "polity-president-pm-87", "question": "Who was the first woman Prime Minister of India?", "options": ["Sarojini Naidu", "Sucheta Kripalani", "Pratibha Patil", "Indira Gandhi"], "answer": 3, "explanation": "Indira Gandhi became Prime Minister in January 1966. Sucheta Kripalani was the first woman Chief Minister (U.P., 1963) and Pratibha Patil the first woman President.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "polity-president-pm-88", "question": "Under Article 75(2), Union ministers hold office during the pleasure of the:", "options": ["President", "Prime Minister", "Lok Sabha", "Chief Justice of India"], "answer": 0, "explanation": "Ministers hold office during the President's pleasure, which in practice means while they keep the Prime Minister's confidence and the Ministry keeps the Lok Sabha's.", "difficulty": "easy", "source": "SSC CGL · RRB NTPC"},
  {"id": "polity-president-pm-89", "question": "Who served twice as interim Prime Minister, after the deaths of Jawaharlal Nehru and Lal Bahadur Shastri?", "options": ["Morarji Desai", "Y. B. Chavan", "Gulzarilal Nanda", "Jagjivan Ram"], "answer": 2, "explanation": "Gulzarilal Nanda was acting Prime Minister for about two weeks each time, in 1964 and 1966. Morarji Desai became the first non-Congress PM in 1977.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "polity-president-pm-90", "question": "Under Article 66, the Vice-President is elected by:", "options": ["Direct election by the people", "Proportional representation by the single transferable vote, by secret ballot", "A simple majority vote in the Rajya Sabha", "Open ballot of both Houses of Parliament"], "answer": 1, "explanation": "The electoral college of all members of both Houses votes by proportional representation through the single transferable vote, and the voting is by secret ballot.", "difficulty": "moderate", "source": "SSC CGL · State PSCs"},
  {"id": "polity-president-pm-91", "question": "Which two Presidents of India died in office?", "options": ["Zakir Husain and Fakhruddin Ali Ahmed", "Rajendra Prasad and Zakir Husain", "Fakhruddin Ali Ahmed and Giani Zail Singh", "V. V. Giri and Zakir Husain"], "answer": 0, "explanation": "Zakir Husain died in May 1969 and Fakhruddin Ali Ahmed in February 1977. Each death led to a fresh election within six months as required by Article 62(2).", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "polity-president-pm-92", "question": "Who was elected Vice-President of India in September 2025, after Jagdeep Dhankhar resigned?", "options": ["Om Birla", "Harivansh Narayan Singh", "B. Sudershan Reddy", "C. P. Radhakrishnan"], "answer": 3, "explanation": "C. P. Radhakrishnan defeated the opposition candidate, former Supreme Court judge B. Sudershan Reddy. Harivansh is Deputy Chairman of the Rajya Sabha and Om Birla is Lok Sabha Speaker.", "difficulty": "moderate", "source": "SSC CGL · State PSCs"},
  {"id": "polity-president-pm-93", "question": "Which President of India had earlier been both Chief Minister of Andhra Pradesh and Speaker of the Lok Sabha?", "options": ["V. V. Giri", "N. Sanjiva Reddy", "R. Venkataraman", "K. R. Narayanan"], "answer": 1, "explanation": "N. Sanjiva Reddy was the first Chief Minister of Andhra Pradesh and twice Lok Sabha Speaker before becoming President in 1977. R. Venkataraman had been Vice-President and Defence Minister.", "difficulty": "moderate", "source": "SSC CGL · State PSCs"},
  {"id": "polity-president-pm-94", "question": "Under Article 361, which of these is true of a sitting President?", "options": ["No criminal proceedings may be started against him during his term", "He can be arrested with the permission of the Chief Justice", "Civil proceedings against him need no notice", "He must answer to a court for official acts"], "answer": 0, "explanation": "Article 361 bars criminal proceedings and arrest during the term. Civil proceedings for personal acts need two months' prior notice, and he is not answerable to any court for official acts.", "difficulty": "moderate", "source": "UPSC Prelims · State PSCs"},
  {"id": "polity-president-pm-95", "question": "Which President used the “pocket veto” on the Indian Post Office (Amendment) Bill, 1986?", "options": ["R. Venkataraman", "Neelam Sanjiva Reddy", "Giani Zail Singh", "Shankar Dayal Sharma"], "answer": 2, "explanation": "Zail Singh simply kept the Bill pending, which the Constitution allows since it sets no time limit for assent on ordinary bills. His successor R. Venkataraman returned it to the government.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "polity-president-pm-96", "question": "Which of these Prime Ministers did NOT die while in office?", "options": ["Jawaharlal Nehru", "Lal Bahadur Shastri", "Indira Gandhi", "Rajiv Gandhi"], "answer": 3, "explanation": "Nehru (1964), Shastri (1966) and Indira Gandhi (1984) died as PM. Rajiv Gandhi was assassinated in May 1991, when he was no longer Prime Minister.", "difficulty": "hard", "source": "SSC CGL · State PSCs"},
  {"id": "polity-president-pm-97", "question": "Which of these was a member of the Rajya Sabha when first appointed Prime Minister?", "options": ["Morarji Desai", "Indira Gandhi", "Rajiv Gandhi", "Chandra Shekhar"], "answer": 1, "explanation": "Indira Gandhi was a Rajya Sabha member when she became PM in January 1966; she entered the Lok Sabha in 1967. The Constitution lets a PM come from either House.", "difficulty": "hard", "source": "UPSC Prelims · State PSCs"},
  {"id": "polity-president-pm-98", "question": "Who discharged the functions of the President after the death of Fakhruddin Ali Ahmed in February 1977?", "options": ["Vice-President B. D. Jatti", "Chief Justice A. N. Ray", "Vice-President G. S. Pathak", "Speaker N. Sanjiva Reddy"], "answer": 0, "explanation": "Vice-President B. D. Jatti acted as President until N. Sanjiva Reddy took office in July 1977. G. S. Pathak was Vice-President from 1969 to 1974.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "polity-president-pm-99", "question": "In Krishna Kumar Singh v. State of Bihar (2017), a seven-judge bench held that:", "options": ["Ordinances are wholly immune from judicial review", "Re-promulgating ordinances without placing them before the legislature is a fraud on the Constitution", "An ordinance lapses six weeks after it is promulgated", "Only the President, not a Governor, can issue ordinances"], "answer": 1, "explanation": "The Court condemned serial re-promulgation and held that ordinances are subject to judicial review. An ordinance lapses six weeks after the legislature reassembles, not after promulgation.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "polity-president-pm-100", "question": "Which Amendment first made it expressly binding on the President to act in accordance with the advice of the Council of Ministers?", "options": ["24th Amendment, 1971", "44th Amendment, 1978", "42nd Amendment, 1976", "38th Amendment, 1975"], "answer": 2, "explanation": "The 42nd Amendment amended Article 74(1) to say the President “shall” act on advice. The 44th then let him return the advice once for reconsideration.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "polity-president-pm-101", "question": "Which case held that the President and Governors are constitutional heads who must ordinarily act on the aid and advice of their ministers, except in matters left to their discretion?", "options": ["Samsher Singh v. State of Punjab (1974)", "S. R. Bommai v. Union of India (1994)", "Kesavananda Bharati (1973)", "R. C. Cooper v. Union of India (1970)"], "answer": 0, "explanation": "A seven-judge bench in Samsher Singh said the Constitution follows the British model of a constitutional head. Bommai dealt with President's Rule and R. C. Cooper with bank nationalisation.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "polity-president-pm-102", "question": "Consider the following statements: 1. Cabinet committees are provided for in the Constitution. 2. The Appointments Committee of the Cabinet is headed by the Prime Minister. Which of the above is/are correct?", "options": ["1 only", "2 only", "Both 1 and 2", "Neither 1 nor 2"], "answer": 1, "explanation": "Only 2 is correct. Cabinet committees are extra-constitutional bodies set up under the Government of India (Transaction of Business) Rules. The PM heads key ones such as Appointments and Security.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "polity-president-pm-103", "question": "Under Article 73, the executive power of the Union extends to:", "options": ["Only matters in the Union List", "All matters in all three Lists, without exception", "Matters on which Parliament can make laws, and rights exercisable by the Government of India under treaties or agreements", "Only matters relating to defence and foreign affairs"], "answer": 2, "explanation": "Article 73 makes Union executive power co-extensive with Parliament's legislative power, plus treaty rights. On Concurrent List matters it does not extend into States unless the Constitution or Parliament so provides.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "polity-president-pm-104", "question": "Since 1977, every President of India has taken the oath of office on the same date. Which date?", "options": ["26 January", "15 August", "24 July", "25 July"], "answer": 3, "explanation": "N. Sanjiva Reddy took office on 25 July 1977, and since each President has served a full five-year term, every successor has been sworn in on 25 July.", "difficulty": "hard", "source": "SSC CGL · State PSCs"},
  {"id": "polity-president-pm-105", "question": "Consider the following statements: 1. A Governor cannot pardon a death sentence, though he can suspend, remit or commute it. 2. A Governor cannot grant clemency for a sentence passed by a court martial. Which of the above is/are correct?", "options": ["1 only", "2 only", "Both 1 and 2", "Neither 1 nor 2"], "answer": 2, "explanation": "Both are correct. Under Article 72 only the President can pardon a death sentence or deal with court-martial sentences; Article 161 gives the Governor no power over court martial.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "polity-president-pm-106", "question": "Consider the following statements: 1. P. V. Narasimha Rao was not a member of either House of Parliament when he became Prime Minister in 1991. 2. H. D. Deve Gowda was a member of the Rajya Sabha when he became Prime Minister in 1996. Which of the above is/are correct?", "options": ["1 only", "2 only", "Both 1 and 2", "Neither 1 nor 2"], "answer": 0, "explanation": "Only 1 is correct: Rao entered the Lok Sabha through the Nandyal by-election. Deve Gowda was Chief Minister of Karnataka when appointed and was elected to the Rajya Sabha afterwards, within the six months allowed by Article 75(5).", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-president-pm-107", "question": "How many of these statements about the President's ordinance power are correct? I. In R. C. Cooper (1970), the Court indicated that the President's satisfaction could be questioned in court. II. The 38th Amendment (1975) made that satisfaction final and beyond judicial review. III. The 44th Amendment (1978) removed that protection. IV. Under Article 123(2), the President may withdraw an ordinance at any time.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are correct. After the 44th Amendment, the President's satisfaction can be challenged on grounds such as mala fides.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-president-pm-108", "question": "Arrange these Prime Ministers in the order in which they first took office: 1. I. K. Gujral 2. V. P. Singh 3. Charan Singh 4. Atal Bihari Vajpayee", "options": ["3, 2, 1, 4", "2, 3, 4, 1", "3, 4, 2, 1", "3, 2, 4, 1"], "answer": 3, "explanation": "Charan Singh (1979), V. P. Singh (1989), Vajpayee (May 1996, for 13 days) and Gujral (1997).", "difficulty": "very-hard", "source": "UPSC Prelims · State PSCs"},
  {"id": "polity-president-pm-109", "question": "Arrange these Presidents in the order in which they held office: 1. R. Venkataraman 2. Shankar Dayal Sharma 3. Fakhruddin Ali Ahmed 4. Pranab Mukherjee", "options": ["3, 1, 2, 4", "1, 3, 2, 4", "3, 2, 1, 4", "3, 1, 4, 2"], "answer": 0, "explanation": "Fakhruddin Ali Ahmed (1974–77), R. Venkataraman (1987–92), Shankar Dayal Sharma (1992–97) and Pranab Mukherjee (2012–17).", "difficulty": "very-hard", "source": "SSC CGL · State PSCs"},
  {"id": "polity-president-pm-110", "question": "Consider the following statements: 1. The President's oath includes a pledge to “preserve, protect and defend the Constitution and the law”. 2. The Vice-President's oath contains the same pledge. Which of the above is/are correct?", "options": ["1 only", "2 only", "Both 1 and 2", "Neither 1 nor 2"], "answer": 0, "explanation": "Only 1 is correct (Article 60). Under Article 69 the Vice-President swears to bear true faith and allegiance to the Constitution and to faithfully discharge his duty, without the “preserve, protect and defend” clause.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-president-pm-111", "question": "Assertion (A): The President can promulgate an ordinance on a subject on which Parliament has no power to legislate. Reason (R): The ordinance-making power of the President is co-extensive with the legislative power of Parliament.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 3, "explanation": "A is false and R is true. Because the ordinance power mirrors Parliament’s power (Article 123(3)), an ordinance can deal only with Union List and Concurrent List matters and is void to the extent Parliament could not enact it.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-president-pm-112", "question": "Consider the following statements: 1. Article 74 classifies Union ministers into Cabinet ministers, ministers of state and deputy ministers. 2. A Minister of State with independent charge is a member of the Cabinet. Which of the above is/are correct?", "options": ["1 only", "2 only", "Both 1 and 2", "Neither 1 nor 2"], "answer": 3, "explanation": "Neither is correct. The Constitution does not grade ministers; the ranks come from convention. A Minister of State with independent charge is not a Cabinet member and attends Cabinet meetings only when invited.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-president-pm-113", "question": "How many of these statements about President Droupadi Murmu are correct? I. She is the first President born after independence. II. She is the first person from a Scheduled Tribe to become President. III. She was earlier Governor of Jharkhand. IV. She won the 2022 election against Yashwant Sinha.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are correct. She was born in 1958, was Governor of Jharkhand from 2015 to 2021, and became the 15th President in July 2022.", "difficulty": "very-hard", "source": "SSC CGL · State PSCs"},
  {"id": "polity-president-pm-114", "question": "Which of these can the President NOT do on his own, without the written decision of the Union Cabinet?", "options": ["Return the advice of the Council of Ministers once for reconsideration", "Proclaim a National Emergency under Article 352", "Choose a Prime Minister when no party has a clear majority", "Ask the Prime Minister for information on proposals for legislation under Article 78"], "answer": 1, "explanation": "After the 44th Amendment, Article 352(3) requires the Cabinet's decision communicated in writing before an Emergency is proclaimed. The other options fall within the President's limited situational discretion.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-president-pm-115", "question": "Who is the ex officio Chairperson of NITI Aayog, the body that replaced the Planning Commission in 2015?", "options": ["The President", "The Union Finance Minister", "The Prime Minister", "The Vice-President"], "answer": 2, "explanation": "The Prime Minister chairs NITI Aayog, set up by a Cabinet resolution on 1 January 2015, just as he chaired the Planning Commission. It is neither a constitutional nor a statutory body.", "difficulty": "moderate", "source": "SSC CGL · RRB NTPC"},
  {"id":"polity-president-pm-116","question":"In a presidential election, the total value of valid votes polled is 10,86,431. Under the single transferable vote system, what quota of votes must a candidate secure to be declared elected?","options":["5,43,216","5,43,215","7,24,288","No fixed figure; the candidate with the most first preferences wins"],"answer":0,"explanation":"The quota is half the valid votes, ignoring any fraction, plus one: 5,43,215 + 1 = 5,43,216. Plurality does not decide; second and later preferences are transferred until a candidate reaches the quota.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-president-pm-117","question":"A State's population, as per the Census used for the presidential election, is 4,31,25,000 and its Assembly has 150 elected members. What is the value of each MLA's vote?","options":["287","288","2,875","28,750"],"answer":1,"explanation":"4,31,25,000 ÷ 150 = 2,87,500; dividing by 1,000 gives 287 with a remainder of 500. Under Article 55(2)(b), a remainder of not less than 500 adds one, so the value is 288.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-president-pm-118","question":"If the President is impeached under Article 61, from when does his removal take effect?","options":["From the date the Chief Justice of India certifies the result","From the date his successor enters office","From the date the second House passes the resolution by a two-thirds majority of its total membership","From the date at least half the State legislatures endorse the resolution"],"answer":2,"explanation":"Article 61(4) removes the President from the date the investigating House passes the resolution. States play no part in impeachment.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-president-pm-119","question":"Consider the following statements: 1. A President elected to fill a vacancy caused by death holds office only for the rest of his predecessor's term. 2. A President whose term has expired continues in office until his successor enters office. Which of the above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":1,"explanation":"Under Article 62(2), a President elected to fill a vacancy gets a full five-year term, so 1 is wrong. Article 56(1)(c) provides for continuity until the successor takes over.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-president-pm-120","question":"Several State Assemblies stand dissolved when a presidential election is held. Which statement is correct?","options":["The election must be postponed until all Assemblies are reconstituted","The election is valid only if the Supreme Court permits it under Article 143","The election is void if more than one-fourth of the electoral college is vacant","The election cannot be questioned on the ground of any vacancy in the electoral college"],"answer":3,"explanation":"Article 71(4), added by the 11th Amendment (1961), bars a challenge on the ground of vacancies in the electoral college for whatever reason.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-president-pm-121","question":"If the Supreme Court declares a President's election void, what happens to the acts he performed in office before that decision?","options":["They remain valid","They become void from the start","They remain valid only if Parliament ratifies them","They lapse unless the new President confirms them within six months"],"answer":0,"explanation":"Article 71(2) expressly protects acts done in the exercise of the office before the date of the Supreme Court's decision.","difficulty":"moderate","source":"UPSC Prelims · State PSCs"},
  {"id":"polity-president-pm-122","question":"Before the 11th Amendment (1961), how was the Vice-President elected?","options":["By an electoral college of elected MPs and MLAs, like the President","By the Rajya Sabha alone","By the members of both Houses assembled at a joint meeting","By the Lok Sabha alone, on the Prime Minister's nomination"],"answer":2,"explanation":"Article 66 originally provided for election at a joint meeting of both Houses. The 11th Amendment replaced this with an electoral college of members of both Houses, so a joint sitting is no longer needed.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-president-pm-123","question":"A sitting member of the Lok Sabha is elected President of India. When does his seat in the Lok Sabha become vacant?","options":["On the date the election result is declared","On the date the Speaker accepts his resignation","Only when he resigns his seat within 14 days","On the date he enters upon his office as President"],"answer":3,"explanation":"Article 59(1) deems his seat vacated from the date he enters office. No resignation is needed.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-president-pm-124","question":"In Shatrughan Chauhan v. Union of India (2014), the Supreme Court held that:","options":["undue and unexplained delay in deciding a mercy petition is a ground for commuting a death sentence to life imprisonment","the President's decision on a mercy petition can never be reviewed by a court","the President must give the convict an oral hearing before deciding a mercy petition","a mercy petition must be decided by the President personally, without ministerial advice"],"answer":0,"explanation":"The Court treated long, unexplained delay as a supervening circumstance that justifies commutation. Kehar Singh (1989) had held there is no right to an oral hearing, and Maru Ram that the power is exercised on advice.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-president-pm-125","question":"A Governor reserves a State Bill (not a Money Bill) for the President's consideration. Under Article 201, which statement is correct?","options":["The President must give or withhold assent within six months","The President may direct the Governor to return the Bill; the legislature must reconsider it within six months, and even if it is passed again the President is not bound to assent","If the legislature passes the Bill again after it is returned, the President must give assent","The President must send the Bill to the Supreme Court before withholding assent"],"answer":1,"explanation":"Unlike Article 111 for Parliament, Article 201 does not compel assent after the Bill is passed again. The six-month limit is for the State legislature's reconsideration.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-president-pm-126","question":"Assertion (A): The Indian President's suspensive veto is weaker than the qualified veto of the US President. Reason (R): Parliament can override the Indian President's return of a Bill by passing it again by a simple majority, whereas the US Congress needs a two-thirds majority in each House.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Under Article 111, once a returned Bill is passed again, with or without amendments, the President cannot withhold assent. An ordinary majority overrides him, which is why the veto is only suspensive.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-president-pm-127","question":"An ordinance is promulgated during a recess. The Lok Sabha reassembles on 1 July and the Rajya Sabha on 8 July. Unless approved or disapproved earlier, the ordinance ceases to operate on:","options":["12 August","19 August","8 September","8 January of the next year"],"answer":1,"explanation":"Under Article 123(2), six weeks run from the later date of reassembly: 8 July + 42 days = 19 August. Counting from 1 July gives the trap answer of 12 August.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-president-pm-128","question":"Consider the following statements about Article 77: 1. All executive action of the Government of India is expressed to be taken in the name of the President. 2. The validity of an order authenticated in the manner prescribed by the rules cannot be questioned on the ground that it was not made or executed by the President. 3. The rules for allocating the business of the Government among ministers are made by the Prime Minister. Which of the above are correct?","options":["1 only","2 and 3 only","1 and 2 only","1, 2 and 3"],"answer":2,"explanation":"Article 77(3) gives the rule-making power to the President, though he acts on advice. Clauses (1) and (2) support statements 1 and 2.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-president-pm-129","question":"A non-member is appointed minister, fails to get elected within six months and resigns, and is then reappointed without being elected. In S. R. Chaudhuri v. State of Punjab (2001), the Supreme Court held that:","options":["the reappointment is valid, since each appointment gets a fresh six months","the reappointment is valid if the Governor records reasons","the reappointment is valid if the person contests a by-election within the new six months","the reappointment during the same legislature's term is impermissible, as it subverts the Constitution"],"answer":3,"explanation":"The six-month window under Articles 75(5) and 164(4) is a one-time exception. Repeating it in the same term without election is a fraud on the Constitution.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-president-pm-130","question":"A legislator is disqualified under the Tenth Schedule for defection. Which of the following follow? 1. He cannot be appointed a minister until his term ends or he is re-elected, whichever is earlier. 2. He cannot hold any remunerative political post for the same period. 3. He is barred from contesting any election for six years.","options":["1 only","2 and 3 only","1 and 2 only","1, 2 and 3"],"answer":2,"explanation":"The 91st Amendment added Articles 75(1B), 164(1B) and 361B. There is no six-year ban on contesting; the defector can seek re-election straight away.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-president-pm-131","question":"In U. N. R. Rao v. Indira Gandhi (1971), the Supreme Court held that when the Lok Sabha is dissolved:","options":["the Council of Ministers does not cease to hold office, since the President cannot exercise executive power without its aid and advice","the Council of Ministers ceases at once and the President governs alone until the new Lok Sabha meets","the Council of Ministers continues, but cannot advise the President on any matter","the Vice-President heads an interim council chosen by the President"],"answer":0,"explanation":"Article 74(1) is mandatory: there must always be a Council of Ministers to advise the President. This is the constitutional basis for a caretaker government.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-president-pm-132","question":"Consider the following statements: 1. The death or resignation of the Prime Minister automatically dissolves the Council of Ministers. 2. The resignation of any Cabinet Minister also dissolves the Council of Ministers. Which of the above is/are correct?","options":["2 only","Both 1 and 2","Neither 1 nor 2","1 only"],"answer":3,"explanation":"The Council exists around the Prime Minister, so it falls with him. Another minister's exit only creates a vacancy that the Prime Minister may fill.","difficulty":"moderate","source":"UPSC Prelims · State PSCs"},
  {"id":"polity-president-pm-133","question":"The President can summon a joint sitting of the two Houses under Article 108 to resolve a deadlock on which of the following? 1. An ordinary Bill rejected by the other House. 2. A Money Bill. 3. A Constitution Amendment Bill.","options":["1 and 2 only","1 only","1 and 3 only","1, 2 and 3"],"answer":1,"explanation":"A Money Bill cannot deadlock, since the Rajya Sabha can only delay it for 14 days, and a Constitution Amendment Bill must pass each House separately under Article 368.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-president-pm-134","question":"Which of the following Bills need the President's prior recommendation before they can be introduced in Parliament? 1. A Money Bill. 2. A Bill under Article 3 to form a new State. 3. A Constitution Amendment Bill.","options":["1 only","2 and 3 only","1 and 2 only","1, 2 and 3"],"answer":2,"explanation":"Articles 117(1) and 3 require prior recommendation for 1 and 2. A Constitution Amendment Bill needs no recommendation and may even be a private member's Bill.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-president-pm-135","question":"The supreme command of the Defence Forces is vested in the President under Article 53(2). How is its exercise limited?","options":["It can be exercised only during a National Emergency","It is exercised only on the written decision of the Union Cabinet under Article 352","It is exercised by the Chief of Defence Staff independently of any law","Its exercise is regulated by law"],"answer":3,"explanation":"Article 53(2) says the exercise of the supreme command shall be regulated by law, which means Parliament controls it. The Cabinet's written decision is required only for an emergency proclamation.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-president-pm-136","question":"How does the position of the Rajya Sabha's Chairman, when a resolution for his removal is under consideration, differ from that of the Lok Sabha Speaker in the same situation?","options":["The Chairman has a casting vote, whereas the Speaker cannot vote at all","The Chairman cannot vote at all on the resolution, whereas the Speaker may vote in the first instance but not in case of a tie","Both may vote in the first instance, and neither has a casting vote","Neither may speak in the House while the resolution is under consideration"],"answer":1,"explanation":"Under Article 92(2), the Chairman, who is not a member of the House, may speak but not vote at all. Article 96(2) lets the Speaker vote in the first instance only.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-president-pm-137","question":"Consider the following statements about the presidential election: 1. Voting is by secret ballot. 2. An MP who votes against his party's line is disqualified under the Tenth Schedule. 3. Members of State Legislative Councils also vote. Which of the above is/are correct?","options":["1 only","1 and 2 only","1 and 3 only","1, 2 and 3"],"answer":0,"explanation":"Article 55(3) prescribes a secret ballot. The Tenth Schedule covers voting in a House, not in the presidential electoral college, and Council members have no vote.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-president-pm-138","question":"The President addresses his resignation to the Vice-President. Under Article 56(2), the Vice-President must forthwith communicate it to the:","options":["Chairman of the Rajya Sabha","Chief Justice of India","Speaker of the Lok Sabha","Prime Minister"],"answer":2,"explanation":"Article 56(2) requires the resignation to be communicated to the Speaker of the Lok Sabha. The Vice-President is himself the Rajya Sabha's Chairman, so that option is a trap.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-president-pm-139","question":"Under Article 80(3), the twelve members nominated by the President to the Rajya Sabha must have special knowledge or practical experience in:","options":["literature, science, art and sports","art, law, journalism and social service","science, sports, economics and literature","literature, science, art and social service"],"answer":3,"explanation":"Article 80(3) names only literature, science, art and social service. Sportspersons have been nominated under ‘social service’; sport is not listed.","difficulty":"moderate","source":"UPSC Prelims · SSC CGL"},
  {"id":"polity-president-pm-140","question":"Article 74(2) bars courts from inquiring whether, and what, advice was tendered by ministers to the President. In S. R. Bommai (1994), the Supreme Court held that:","options":["the bar also covers the material on which the advice was based","the material on which the advice was based is not part of the advice and can be examined by the court","Article 74(2) applies only to advice given during an emergency","the President must disclose the advice to the court when asked"],"answer":1,"explanation":"The Court separated the advice, which is protected, from the supporting material, which is open to scrutiny. This let it review the basis of Article 356 proclamations.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-president-pm-141","question":"Which of these bodies is NOT chaired by the Prime Minister?","options":["Zonal Council","National Disaster Management Authority","Inter-State Council","Governing Council of NITI Aayog"],"answer":0,"explanation":"Zonal Councils are chaired by the Union Home Minister. The Prime Minister chairs the NDMA (by law), the Inter-State Council and NITI Aayog.","difficulty":"moderate","source":"UPSC Prelims · SSC CGL"},
  {"id":"polity-president-pm-142","question":"Under Article 86(2), the President may send messages to either House of Parliament. Which statement about this power is correct?","options":["Messages may be sent only through the Prime Minister and only on Money Bills","Messages may concern a Bill pending in Parliament or any other matter, and the House must consider them with all convenient despatch","Messages may be sent only to a joint sitting of both Houses","Messages are advisory and the House may decline to take them up"],"answer":1,"explanation":"Article 86(2) covers pending Bills ‘or otherwise’ and obliges the House to consider the message with all convenient despatch. It is separate from the address to Parliament under Articles 86(1) and 87.","difficulty":"moderate","source":"UPSC Prelims · State PSCs"},
  {"id":"polity-president-pm-143","question":"Consider the following statements about the Vice-President: 1. He is eligible for re-election any number of times. 2. A resolution for his removal originates in the Lok Sabha and must be agreed to by the Rajya Sabha. 3. At least 14 days' notice must be given before such a resolution is moved. Which of the above are correct?","options":["1 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"answer":2,"explanation":"Under Article 67(b), the resolution is passed by the Rajya Sabha (majority of all its then members) and agreed to by the Lok Sabha, the reverse of statement 2. Nothing bars re-election.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-president-pm-144","question":"The office of President falls vacant on the President's death. For how long does the Vice-President act as President?","options":["Until the new President, who must be elected within six months, enters upon office","For the rest of the deceased President's term","For a maximum of six months, after which the Chief Justice of India takes over","Until Parliament elects an acting President at a joint sitting"],"answer":0,"explanation":"Article 65(1) makes the Vice-President act until the new President enters office, and Article 62(2) requires the election within six months. The CJI steps in only if the Vice-President's office is also vacant.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-president-pm-145","question":"In which of these situations can the President exercise a real, situational discretion rather than simply act on ministerial advice?","options":["Returning a Money Bill to the Lok Sabha for reconsideration","Appointing the Chief Justice of India","Promulgating an ordinance during a recess","Choosing a Prime Minister when no party or coalition has a clear majority in the Lok Sabha"],"answer":3,"explanation":"With no clear majority there is no advice to follow, so the President must judge who can command confidence. A Money Bill cannot be returned at all, and ordinances and judicial appointments follow advice and consultation.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-president-pm-146","question":"Under the Presidential and Vice-Presidential Elections Act, 1952, an election petition challenging the election of the President may be presented by:","options":["any candidate at the election, or twenty or more electors joined together as petitioners","any single elector of the electoral college","the Attorney General alone, on the Union Government's instruction","any candidate, or fifty or more electors joined together as petitioners"],"answer":0,"explanation":"Section 14A allows a candidate or at least twenty electors jointly (ten for the Vice-President's election), and the petition goes to the Supreme Court. Fifty is the number of proposers needed for a presidential nomination.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-president-pm-147","question":"Why did the Constituent Assembly prefer an indirect election for the President over a direct popular vote?","options":["Direct elections were barred by the Government of India Act, 1935","A head of state with only nominal powers did not need a nationwide mandate, which could also set him up as a rival to the Prime Minister","The States insisted that only their legislatures should elect the head of state","An indirect election made it possible to give each State an equal number of votes"],"answer":1,"explanation":"Members felt a directly elected but nominal President would be an anomaly and a costly exercise, and could clash with the Prime Minister's popular mandate in a parliamentary system.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-president-pm-148","question":"Consider the following statements: 1. As in Britain, the Constitution requires every public order of the President to be countersigned by a minister. 2. Courts cannot inquire into whether, and what, advice was tendered by ministers to the President. Which of the above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":1,"explanation":"India has no countersignature rule, so ministers bear no legal responsibility of the British kind. Article 74(2) puts the advice itself beyond judicial inquiry.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-president-pm-149","question":"Consider the following statements about the lists of Scheduled Castes under Article 341: 1. The President first specifies the castes for a State by public notification, after consulting the Governor. 2. The President can later modify that list by issuing a fresh notification. 3. Parliament can include or exclude castes from the list by law. Which of the above are correct?","options":["1 only","1 and 2 only","1 and 3 only","1, 2 and 3"],"answer":2,"explanation":"Article 341(2) says the notified list cannot be varied by any later notification; only Parliament can change it by law. Article 342 has the same scheme for Scheduled Tribes.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-president-pm-150","question":"The Contingency Fund of India under Article 267 is placed at the disposal of the:","options":["Comptroller and Auditor General","Union Finance Minister, who uses it without Parliament's approval","Speaker of the Lok Sabha","President, to make advances for unforeseen expenditure pending authorisation by Parliament"],"answer":3,"explanation":"The President holds the Fund and draws advances from it; Parliament later authorises the expenditure and the Fund is recouped. In practice the Finance Ministry operates it on his behalf.","difficulty":"moderate","source":"UPSC Prelims · SSC CGL"},
  {"id":"polity-president-pm-151","question":"Consider the following statements: 1. No demand for a grant can be made except on the President's recommendation. 2. The President causes the annual financial statement to be laid before both Houses. 3. The President can reduce the amount of a demand for grant after it is presented. Which of the above are correct?","options":["1 and 2 only","2 only","1 and 3 only","1, 2 and 3"],"answer":0,"explanation":"Articles 112 and 113(3) support 1 and 2. Only the Lok Sabha can assent to, refuse or reduce a demand; the President has no such power.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-president-pm-152","question":"The first motion of no-confidence in the Lok Sabha was moved in 1963 against the government of which Prime Minister?","options":["Lal Bahadur Shastri","Indira Gandhi","Jawaharlal Nehru","Morarji Desai"],"answer":2,"explanation":"Acharya J. B. Kripalani moved it against Nehru's government after the 1962 war; it was defeated. Collective responsibility to the Lok Sabha (Article 75(3)) makes this motion possible.","difficulty":"hard","source":"UPSC Prelims · State PSCs"},
  {"id":"polity-president-pm-153","question":"Which pair of Presidents is known for having withheld assent to a Bill outright, the ‘absolute veto’?","options":["Zail Singh (Indian Post Office (Amendment) Bill) and K. R. Narayanan","A. P. J. Abdul Kalam (Office of Profit Bill, 2006) and Pratibha Patil","V. V. Giri and Fakhruddin Ali Ahmed","Rajendra Prasad (PEPSU Appropriation Bill, 1954) and R. Venkataraman (MPs' salary and pension amendment Bill, 1991)"],"answer":3,"explanation":"Prasad and Venkataraman withheld assent outright. Zail Singh's was a pocket veto (no decision), and Kalam returned his Bill for reconsideration and signed it when it was passed again.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-president-pm-154","question":"Despite the immunity under Article 361(1), the President's conduct may be brought under review by:","options":["a court, tribunal or body appointed or designated by either House to investigate a charge for impeachment","the Supreme Court, through a writ petition under Article 32","the Comptroller and Auditor General","a committee of Governors constituted by the Inter-State Council"],"answer":0,"explanation":"The proviso to Article 361(1) preserves review only for the purpose of impeachment under Article 61. Ordinary courts cannot call the President to account for official acts.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-president-pm-155","question":"Article 53(3) provides that nothing in Article 53 shall prevent:","options":["the Prime Minister from exercising the executive power directly","Parliament from conferring functions by law on authorities other than the President","State Governments from overriding Union executive orders","the Supreme Court from exercising executive power during an emergency"],"answer":1,"explanation":"Although executive power is vested in the President, Parliament may vest statutory functions in other authorities. Clause (3) also keeps functions already given to State Governments by existing law with them.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-president-pm-156","question":"Which statement about the re-election of the President of India is correct?","options":["Like the US President, he may serve at most two terms","He may serve only one term","He is eligible for re-election any number of times","He may be re-elected only with Parliament's approval"],"answer":2,"explanation":"Article 57 places no limit on re-election. Rajendra Prasad remains the only President elected twice.","difficulty":"moderate","source":"UPSC Prelims · SSC CGL"},
  {"id":"polity-president-pm-157","question":"Assertion (A): A Union minister who is a member of the Rajya Sabha is answerable to the Lok Sabha for the government's policies. Reason (R): Article 75(3) makes the Council of Ministers collectively responsible to the Lok Sabha.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Collective responsibility binds every minister, whichever House he belongs to, to the Lok Sabha. The Rajya Sabha cannot remove the government.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-president-pm-158","question":"Under the proviso to Article 239AA(4), if the Lieutenant Governor of Delhi and his ministers differ on a matter, the Lieutenant Governor:","options":["must accept the advice of the Council of Ministers","decides the matter himself in his discretion","refers it to the Delhi Legislative Assembly","refers it to the President for decision and acts on that decision"],"answer":3,"explanation":"The proviso lets the LG refer a difference to the President. In 2018 the Supreme Court held that this is for exceptional matters, not every difference.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-president-pm-159","question":"A Governor cannot promulgate an ordinance without instructions from the President if, had the same provisions been in a Bill:","options":["it would have been a Money Bill","the Legislative Council would have had to consider it","the President's previous sanction would have been needed to introduce it","the Governor's recommendation would have been needed to introduce it"],"answer":2,"explanation":"The proviso to Article 213(1) also covers provisions the Governor would have reserved, or that would be invalid without the President's assent. The other options need no Presidential instruction.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-president-pm-160","question":"In B. P. Singhal v. Union of India (2010), on removing Governors, the Supreme Court held that:","options":["a Governor has a fixed term of five years and can be removed only by impeachment","although Governors hold office at the President's pleasure, they cannot be removed arbitrarily, such as merely because the Union Government has changed","the President may remove a Governor only on the State legislature's resolution","the removal of a Governor can never be examined by a court"],"answer":1,"explanation":"The pleasure doctrine under Article 156 stands, but removal needs valid reasons; a change of party at the Centre or a difference in ideology is not enough. Limited judicial review is available.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-president-pm-161","question":"Assertion (A): Although Union ministers hold office during the President's pleasure, the President cannot dismiss a Prime Minister who enjoys the confidence of the Lok Sabha. Reason (R): Under Article 74(1), the President must act in accordance with the advice of the Council of Ministers headed by the Prime Minister.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"The pleasure under Article 75(2) is exercised on advice, and a PM with a majority will not advise his own dismissal. In practice the pleasure lasts as long as the Lok Sabha's confidence.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-president-pm-162","question":"The salaries and allowances of Union ministers are determined by:","options":["the President, by order","the Union Cabinet","the Central Pay Commission","Parliament, by law"],"answer":3,"explanation":"Article 75(6) leaves ministers' salaries to Parliament (until then, the Second Schedule). The President's own emoluments are also fixed by Parliament under Article 59(3).","difficulty":"moderate","source":"UPSC Prelims · SSC CGL"},
  {"id":"polity-president-pm-163","question":"Consider the following statements: 1. A Vice-President whose term has expired continues in office until his successor enters office. 2. An election to fill a vacancy in the Vice-President's office caused by death must be held within six months. Which of the above is/are correct?","options":["2 only","Both 1 and 2","1 only","Neither 1 nor 2"],"answer":2,"explanation":"Article 67(c) supports 1. Article 68(2) requires the election to be held ‘as soon as possible’; the six-month limit applies only to the President's office under Article 62(2).","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-president-pm-164","question":"Consider the following statements: 1. A Union minister who disagrees with a Cabinet decision must either support it or resign. 2. Under the Lok Sabha's rules, a motion of no-confidence can be moved against an individual minister. Which of the above is/are correct?","options":["2 only","1 only","Both 1 and 2","Neither 1 nor 2"],"answer":1,"explanation":"Collective responsibility makes Cabinet decisions binding on all ministers. A no-confidence motion lies only against the Council of Ministers as a whole.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-president-pm-165","question":"A State law is meant to give effect to the Directive Principles in Article 39(b) and (c). Under the proviso to Article 31C, it gets the protection of that Article only if:","options":["it is passed by a two-thirds majority of the State Assembly","the Governor certifies that it gives effect to those Directive Principles","Parliament approves it by resolution","it is reserved for the President's consideration and receives his assent"],"answer":3,"explanation":"Under the proviso, a State law gets the protection only after the President's assent. This gives the Union a check on State laws that would otherwise escape challenge under Articles 14 and 19.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-president-pm-166","question":"Which of these offices is provided for in Chapter I (‘The Executive’) of Part V of the Constitution, as part of the Union executive?","options":["Comptroller and Auditor General","Speaker of the Lok Sabha","Attorney General for India","Chief Election Commissioner"],"answer":2,"explanation":"Article 76 on the Attorney General sits in Chapter I of Part V, alongside the President, Vice-President and Council of Ministers. The CAG is in Chapter V, the Speaker in Chapter II, and the CEC in Part XV.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-president-pm-167","question":"In a presidential election, a State's population (as per the Census in use) is 63,00,000 and its Legislative Assembly has 120 elected members. Applying Article 55(2) exactly, what is the value of the vote of each elected MLA of that State?","options":["53","52","525","54"],"answer":0,"explanation":"63,00,000 ÷ 120 = 52,500, which holds 52 multiples of 1,000 with a remainder of exactly 500. Article 55(2)(b) adds one more vote when the remainder is ‘not less than five hundred’, so the value is 53, not 52.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-president-pm-168","question":"In a hypothetical presidential election, the total value of the votes of all elected MLAs is 5,49,796 and there are 776 elected Members of Parliament. Applying Article 55(2)(c) exactly, what is the value of each MP's vote?","options":["708","709","710","707"],"answer":0,"explanation":"5,49,796 ÷ 776 = 708.5. For MPs, only fractions ‘exceeding one-half’ are counted as one, so an exact half is disregarded and the value is 708. Rounding the half up (709) applies the MLA rule by mistake.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-president-pm-169","question":"Consider the following statements about the immunities of the President under Article 361: 1. No criminal proceedings can be instituted or continued against the President in any court during his term of office. 2. No process for the arrest or imprisonment of the President can issue from any court during his term. 3. Civil proceedings for acts done in his personal capacity can be instituted during his term without any prior notice. 4. The President is not answerable to any court for the exercise of the powers and duties of his office. How many of the above statements are correct?","options":["Only one","Only two","Only three","All four of them"],"answer":2,"explanation":"Statements 1, 2 and 4 restate Article 361(2), (3) and (1). Under Article 361(4), civil proceedings for personal acts need two months' written notice first, so statement 3 is wrong.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-president-pm-170","question":"A person is sentenced to imprisonment (not death) for an offence under a State law made on a subject in the State List. Who can grant him a pardon under the Constitution?","options":["Either the President or the Governor","Only the Governor of that State","Neither, since only the High Court can remit it","Only the President"],"answer":1,"explanation":"Article 72(1)(b) covers offences against laws on matters to which the Union's executive power extends, which excludes State List subjects, and the case is not a death sentence or a court martial. So only the Governor can pardon, under Article 161.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-president-pm-171","question":"Consider the following statements about the advisory jurisdiction of the Supreme Court: 1. On a reference under Article 143(1), the Supreme Court may decline to give its opinion. 2. On a reference under Article 143(2) about a dispute arising from a pre-Constitution treaty or agreement, the Court must give its opinion. 3. The opinion given under Article 143 binds the President. Which of the above is/are correct?","options":["1 and 2 only","1 only","2 and 3 only","1, 2 and 3"],"answer":0,"explanation":"Article 143(1) says the Court ‘may’ report (it declined the Ayodhya reference in 1994), while Article 143(2) says it ‘shall’. The opinion is advisory and does not bind the President.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-president-pm-172","question":"In Ram Jawaya Kapur v. State of Punjab (1955), the Supreme Court explained the executive power under Articles 73 and 162. Which of the following did it hold?","options":["The executive can act only where a law already authorises it, so executive power can never precede legislation","The President is the real executive, and the Council of Ministers is only an advisory body he may ignore","Executive power of a State extends to all subjects in the Concurrent List, unless a Union law is first made","Executive power is what remains once legislative and judicial functions are removed, wielded by the ministry"],"answer":3,"explanation":"The Court described executive function residually and held that India follows the British cabinet system, with the President as formal head. It also held that the executive may act on matters within legislative competence even without a specific law.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-president-pm-173","question":"In S. P. Anand v. H. D. Deve Gowda (1996), a petition challenged the appointment of a Prime Minister who was not a member of either House of Parliament. The Supreme Court held that:","options":["Only a member of the Lok Sabha can be appointed Prime Minister","Such a person can be appointed Prime Minister, subject to becoming a member within six months","A Prime Minister who is not a member must be elected to the Lok Sabha within three months","The appointment was void because Article 75(5) applies only to ministers other than the Prime Minister"],"answer":1,"explanation":"Article 75(5) applies to the Prime Minister too, so a non-member may be appointed and must become a member of either House within six months; the petition was dismissed.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-president-pm-174","question":"Article 361B, inserted by the 91st Amendment, provides that a member of a House disqualified under the Tenth Schedule:","options":["Shall not contest any election to Parliament or a State legislature for six years","Shall be removed from any ministerial post only on the advice of the Election Commission","Shall forfeit his pension as a former member of that House for the rest of his life","Shall hold no remunerative political post till his term ends or he is re-elected, if earlier"],"answer":3,"explanation":"Article 361B bars such a member from any remunerative political post for the same period that Articles 75(1B) and 164(1B) bar him from becoming a minister. There is no six-year election bar for defection.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-president-pm-175","question":"The President returns a Bill (not a Money Bill) to Parliament under Article 111. Both Houses pass it again but accept some amendments while doing so, and send it back. What is the President's position?","options":["He may return it once more, since amendments make it a new Bill","He must assent, since the bar applies whether the Bill is passed again with or without amendment","He may withhold assent, since the bar applies only if the Bill is passed in its original form","He must refer it to the Supreme Court under Article 143 before giving assent"],"answer":1,"explanation":"Article 111 says that if the Bill is passed again ‘with or without amendment’, the President shall not withhold assent. The return is a suspensive veto, usable only once.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-president-pm-176","question":"A Bill passed by both Houses of Parliament is pending the President's assent when the Lok Sabha is dissolved. What happens to the Bill?","options":["It is deemed to have received assent on the date of dissolution","It lapses and must be passed afresh by the new Lok Sabha","It lapses only if it had originated in the Lok Sabha","It does not lapse and can still receive assent"],"answer":3,"explanation":"A Bill passed by both Houses and awaiting assent does not lapse on dissolution. This is why the President's inaction (pocket veto) can outlast a Lok Sabha.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-president-pm-177","question":"Consider the following statements about an ordinance under Article 123: 1. It may be given retrospective effect. 2. It may modify or repeal an Act of Parliament. 3. It may amend the Constitution. 4. The President may withdraw it at any time. How many of the above statements are correct?","options":["Only one","Only two","Only three","All four of them"],"answer":2,"explanation":"An ordinance has the same force as an Act of Parliament, so it can be retrospective and can amend or repeal an Act, and Article 123(2)(b) lets the President withdraw it at any time. A constitutional amendment needs a Bill under Article 368, so 3 is wrong.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-president-pm-178","question":"Suppose the Lok Sabha has a total membership of 543. To impeach the President, what are the minimum number of members who must sign the notice in the Lok Sabha and the minimum number who must vote for the resolution there?","options":["136 and 362","135 and 362","136 and 363","109 and 362"],"answer":0,"explanation":"Article 61 needs a notice signed by at least one-fourth of total membership (543 ÷ 4 = 135.75, so 136) and a resolution passed by at least two-thirds of total membership (543 × 2/3 = 362).","difficulty":"moderate","source":"UPSC Prelims"},
  {"id":"polity-president-pm-179","question":"A Union minister who is a member of the Rajya Sabha completes his term there on 2 April and is not re-elected. Which statement is correct?","options":["He ceases to be a minister on 2 April itself, since membership is a continuing condition","He may continue, but ceases to be a minister after six consecutive months as a non-member","He may continue as minister until the end of the Lok Sabha's term","He may continue only if he is nominated to the Rajya Sabha by the President"],"answer":1,"explanation":"Article 75(5) only says a minister who for six consecutive months is not a member of either House ceases to be a minister at the end of that period; it applies to a sitting minister who loses membership too.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-president-pm-180","question":"The Lok Sabha passes a motion of no-confidence in the Council of Ministers, and the Prime Minister then advises the President to dissolve the Lok Sabha. Which statement best reflects the constitutional position?","options":["The President must dismiss the Prime Minister and appoint the Leader of the Opposition at once","The Rajya Sabha must approve the dissolution before the President can act on the advice","The President is not bound to accept this advice and may first explore whether another government can be formed","The President must dissolve the House, since Article 74(1) makes all ministerial advice binding"],"answer":2,"explanation":"Advice from a ministry that has lost the confidence of the Lok Sabha is the classic case where the President has situational discretion; he may look for an alternative government before ordering dissolution.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-president-pm-181","question":"After the death of President Zakir Husain in 1969, the Vice-President acting as President resigned to contest the election. Who then discharged the functions of the President?","options":["Chief Justice K. Subba Rao","Gopal Swarup Pathak","Chief Justice J. C. Shah","Chief Justice M. Hidayatullah"],"answer":3,"explanation":"With both offices vacant, Chief Justice M. Hidayatullah acted as President from 20 July to 24 August 1969. This led to the President (Discharge of Functions) Act, 1969, which names the CJI and then the senior-most available judge.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-president-pm-182","question":"Consider the following statements about oaths: 1. The Third Schedule prescribes a separate form of oath for the Prime Minister. 2. A Union minister takes an oath of secrecy in addition to an oath of office. 3. The form of the President's oath is given in the Third Schedule. Which of the above is/are correct?","options":["2 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":0,"explanation":"The Prime Minister takes the same oaths of office and secrecy as any Union minister, so 1 is wrong. The President's oath is set out in Article 60 itself, not in the Third Schedule, so 3 is wrong too.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-president-pm-183","question":"Consider the following statements about removing the Vice-President: 1. The Constitution does not state any grounds for removal. 2. The resolution must be passed by a majority of all the then members of the Rajya Sabha and agreed to by the Lok Sabha. 3. At least fourteen days' notice of the intention to move the resolution must be given. How many of the above statements are correct?","options":["Only one","Only two","All three","None of them"],"answer":2,"explanation":"Article 67(b) prescribes an effective majority in the Rajya Sabha, simple agreement by the Lok Sabha and 14 days' notice, but it names no grounds, unlike the President's impeachment for violation of the Constitution.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-president-pm-184","question":"Assertion (A): After the 44th Amendment, the President can refuse to act on advice that the Council of Ministers has reconsidered and tendered again. Reason (R): The proviso to Article 74(1) lets the President require the Council to reconsider its advice.","options":["Both A and R are true, and R explains A","Both A and R are true, but R does not explain A","A is true, but R is false","A is false, but R is true"],"answer":3,"explanation":"R is true, but the same proviso says the President shall act in accordance with the advice tendered after reconsideration, so he cannot refuse it a second time.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-president-pm-185","question":"Assertion (A): The President can remove an individual Union minister even while the Council of Ministers enjoys the confidence of the Lok Sabha. Reason (R): Ministers hold office during the pleasure of the President, which is exercised on the advice of the Prime Minister.","options":["Both A and R are true, and R explains A","Both A and R are true, but R does not explain A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Article 75(2) makes ministers hold office during the President's pleasure; in practice the Prime Minister can have a minister dismissed this way, which is the basis of individual responsibility.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-president-pm-186","question":"A Union minister takes an important decision on his own without placing it before the Council of Ministers. The President wishes it to be considered by the whole Council. Through which provision can this be done?","options":["Article 74(1), by returning the advice for reconsideration","Article 78(c), by requiring the Prime Minister to submit it to the Council","Article 77(3), by amending the rules of business","Article 75(3), by referring the matter to the Lok Sabha for its decision"],"answer":1,"explanation":"Article 78(c) makes it the Prime Minister's duty, if the President so requires, to submit for the Council's consideration any matter decided by a minister but not considered by the Council.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-president-pm-187","question":"How many of the following vote in BOTH the presidential and the vice-presidential elections? 1. Elected members of the Lok Sabha 2. Nominated members of the Rajya Sabha 3. Elected members of State Legislative Assemblies 4. Elected members of the Rajya Sabha","options":["Only one","Only two","Only three","All four of them"],"answer":1,"explanation":"Only elected MPs of both Houses vote in both. Nominated MPs vote only for the Vice-President, and MLAs only for the President.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-president-pm-188","question":"Consider the following statements: 1. In 1997, President K. R. Narayanan returned to the Union Cabinet its recommendation to impose President's Rule in Uttar Pradesh. 2. In 2006, President A. P. J. Abdul Kalam returned the Parliament (Prevention of Disqualification) Amendment Bill on offices of profit and signed it after Parliament passed it again. 3. President Giani Zail Singh kept the Indian Post Office (Amendment) Bill, 1986 pending without a decision. How many of the above statements are correct?","options":["Only one","Only two","All three","None of them"],"answer":2,"explanation":"These are the textbook uses of the proviso to Article 74(1), the suspensive veto under Article 111 (binding once the Bill came back), and the pocket veto.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-president-pm-189","question":"Consider the following statements: 1. The Constitution sets no time limit within which the President must decide on a Bill passed by Parliament. 2. The President may withhold assent to a Money Bill, though he cannot return it for reconsideration. 3. The President must give assent to a Constitution Amendment Bill passed under Article 368. Which of the above is/are correct?","options":["1, 2 and 3","1 and 3 only","2 and 3 only","1 only"],"answer":0,"explanation":"Article 111 has no time limit (hence the pocket veto); a Money Bill can be assented to or withheld but not returned; and since the 24th Amendment, Article 368(2) says the President ‘shall give his assent’.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-president-pm-190","question":"Which one of the following is NOT a power the President exercises under the Constitution in relation to Parliament?","options":["Summoning a joint sitting of the two Houses","Nominating twelve members to the Rajya Sabha","Deciding whether a Bill is a Money Bill","Recommending the introduction of a Money Bill"],"answer":2,"explanation":"Under Article 110(3), the Speaker of the Lok Sabha decides whether a Bill is a Money Bill and his decision is final. The other three are powers of the President under Articles 108, 80 and 117.","difficulty":"moderate","source":"UPSC Prelims"},
  {"id":"polity-president-pm-191","question":"Under Article 55(1), the manner of the presidential election is designed to secure which two kinds of uniformity?","options":["Uniformity between the Lok Sabha and the Rajya Sabha, and parity between elected and nominated members","Equal value for the votes of all States, and parity between the Lok Sabha and the State Assemblies","Equal votes for every MLA and every MP, and equal numbers of electors from each State","Uniformity in the scale of representation of different States, and parity between the States as a whole and the Union"],"answer":3,"explanation":"Vote values for MLAs vary with State population per member, and the total value of MPs' votes is set equal to that of all MLAs, giving parity between the Union and the States.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-president-pm-192","question":"Consider the following statements about a Vice-President acting as President: 1. He has all the powers and immunities of the President. 2. He continues to preside over the Rajya Sabha meanwhile. 3. He is entitled to the emoluments of the President for that period. Which of the above is/are correct?","options":["1 and 3 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":0,"explanation":"Article 65(3) gives him the President's powers, immunities and emoluments, while the proviso to Article 64 says he does not perform the Chairman's duties or draw the Chairman's salary meanwhile.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-president-pm-193","question":"Which one of the following statements about the Prime Minister is correct?","options":["The Constitution requires the President to appoint the leader of the largest party in the Lok Sabha","The Constitution does not lay down any procedure for the selection and appointment of the Prime Minister","The Constitution requires the Prime Minister to win a vote of confidence within one month of appointment","The Constitution fixes a term of five years for the Prime Minister, subject to the Lok Sabha"],"answer":1,"explanation":"Article 75(1) only says the President shall appoint the Prime Minister; who is invited, and any time given to prove a majority, rest on conventions. The PM has no fixed term and holds office during the President's pleasure.","difficulty":"moderate","source":"UPSC Prelims"},
  {"id":"polity-president-pm-194","question":"Arrange in chronological order these Prime Ministers' defeats or resignations: 1. Morarji Desai resigns 2. V. P. Singh loses a vote of confidence 3. Atal Bihari Vajpayee loses a vote of confidence by one vote 4. Charan Singh resigns without facing the Lok Sabha","options":["1, 4, 2, 3","4, 1, 2, 3","1, 4, 3, 2","1, 2, 4, 3"],"answer":0,"explanation":"Desai resigned in July 1979, Charan Singh in August 1979, V. P. Singh lost the confidence vote in November 1990, and Vajpayee lost by one vote in April 1999.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-president-pm-195","question":"Which of the following is correct about the electoral college for the President after the 70th Amendment (1992)?","options":["It includes elected members of State Legislative Councils","It includes nominated members of the Lok Sabha and Rajya Sabha","It includes elected members of the Assemblies of Delhi and Puducherry","It includes elected members of all Union territory Assemblies, including Ladakh"],"answer":2,"explanation":"The Explanation to Article 54, added by the 70th Amendment, treats Delhi and Puducherry as States for this purpose. Council members and nominated MPs never vote, and Ladakh has no legislature.","difficulty":"moderate","source":"UPSC Prelims"},
  {"id":"polity-president-pm-196","question":"In a hypothetical presidential election with three candidates, the total value of valid votes is 10,00,000. First-preference values are: A 4,80,000; B 4,10,000; C 1,10,000. C is eliminated, and his ballots are transferred to the next preference: 95,000 to B and 15,000 to A. What is the result?","options":["No one is elected, and a fresh poll must be held","A is elected, with 4,95,000 against B's 5,05,000","A is elected, having led on first-preference votes","B is elected, having crossed the quota of 5,00,001"],"answer":3,"explanation":"The quota is 10,00,000 ÷ 2 + 1 = 5,00,001. After the transfer B has 5,05,000 and A 4,95,000, so B crosses the quota; a lead on first preferences counts for nothing under the single transferable vote.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-president-pm-197","question":"Which two changes did the 11th Amendment (1961) make regarding the elections of the President and Vice-President?","options":["Delhi and Puducherry Assembly members added to the presidential electoral college, and the nomination deposit raised","MLA vote values frozen on the 1971 Census for presidential elections, and voting by secret ballot made compulsory","Election disputes moved from the Election Commission to the Supreme Court, and nominated MPs barred from voting","Vice-President chosen by an electoral college of both Houses, not a joint meeting; no challenge for electoral-college vacancies"],"answer":3,"explanation":"The 11th Amendment changed Article 66 (electoral college instead of a joint meeting of both Houses) and inserted Article 71(4). Delhi and Puducherry came with the 70th Amendment (1992) and the 1971 freeze with the 84th.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-president-pm-198","question":"Arrange these Presidential references to the Supreme Court under Article 143 in chronological order: 1. Berubari Union 2. Kerala Education Bill 3. Delhi Laws Act 4. Special Courts Bill","options":["3, 2, 1, 4","2, 3, 1, 4","3, 1, 2, 4","2, 1, 3, 4"],"answer":0,"explanation":"In re Delhi Laws Act (1951) was the first reference, followed by the Kerala Education Bill (1958), Berubari Union (1960) and the Special Courts Bill (1978).","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-president-pm-199","question":"Consider the following statements about regulations made by the President under Article 240 for Union territories such as the Andaman and Nicobar Islands: 1. A regulation has the same force and effect as an Act of Parliament. 2. A regulation may repeal or amend an Act of Parliament as it applies to that territory. 3. A regulation must be approved by both Houses of Parliament within six weeks of their reassembly. Which of the above is/are correct?","options":["1 and 2 only","1 only","2 and 3 only","1, 2 and 3"],"answer":0,"explanation":"Article 240(2) gives a regulation the force of an Act of Parliament and lets it repeal or amend any Act of Parliament applicable to the territory. The six-week approval rule applies to ordinances, not regulations.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-president-pm-200","question":"Consider the following statements: 1. Contracts made in the exercise of the executive power of the Union are expressed to be made by the President. 2. Neither the President nor the officer executing such a contract is personally liable on it. 3. The Government of India sues and is sued by the name of the Union of India. How many of the above statements are correct?","options":["Only one","Only two","All three","None of them"],"answer":2,"explanation":"Article 299(1) and (2) give statements 1 and 2, and Article 300(1) gives statement 3.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-president-pm-201","question":"Consider the following statements: 1. The Constitution provides for an acting Vice-President when that office falls vacant. 2. While the Vice-President's office is vacant, the Deputy Chairman performs the duties of the Chairman of the Rajya Sabha. 3. An election to fill a vacancy in the Vice-President's office must be held within six months. Which of the above is/are correct?","options":["2 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":0,"explanation":"There is no acting Vice-President; Article 91 lets the Deputy Chairman perform the Chairman's duties. Article 68(2) asks for the election ‘as soon as possible’, with no six-month limit (that limit is for the President's office).","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-president-pm-202","question":"Consider the following statements about sentences passed by a court martial: 1. The President can pardon a person sentenced by a court martial. 2. Article 72 does not affect the power given by law to officers of the Armed Forces to suspend, remit or commute a court-martial sentence. 3. The Governor can pardon a person sentenced by a court martial. Which of the above is/are correct?","options":["1 and 2 only","1 only","2 and 3 only","1, 2 and 3"],"answer":0,"explanation":"Article 72(1)(a) gives the President this power and Article 72(2) saves the statutory powers of Armed Forces officers. Article 161 gives the Governor no power over court-martial sentences.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-president-pm-203","question":"Consider the following statements comparing the Indian and the US Presidents: 1. The Indian President can dissolve the lower House, which the US President cannot do. 2. Like the US President's veto, the Indian President's veto on an ordinary Bill can be overcome only by a two-thirds majority. 3. Both are removed by impeachment, but in India the only ground is violation of the Constitution. Which of the above is/are correct?","options":["1 and 3 only","1 only","2 and 3 only","1, 2 and 3"],"answer":0,"explanation":"Statement 2 is wrong: the Indian President's veto is suspensive, so Parliament overrides it simply by passing the Bill again with an ordinary majority. The other two are correct.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-president-pm-204","question":"Assertion (A): Article 74 contains no clause, like Article 163(1), reserving any functions to the President's discretion. Reason (R): The 42nd Amendment made the advice of the Council of Ministers binding on the President.","options":["Both A and R are true, and R explains A","Both A and R are true, but R does not explain A","A is true, but R is false","A is false, but R is true"],"answer":1,"explanation":"Both are true, but Article 74 never had a discretion clause, even in 1950; the absence is a feature of the original design, not a result of the 1976 amendment.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-president-pm-205","question":"How many of the following statements about a no-confidence motion in the Lok Sabha are correct? 1. It is not mentioned in the Constitution. 2. It need not state the reasons for its adoption. 3. It can be moved against an individual minister. 4. It needs the support of at least 50 members to be admitted.","options":["Only one","Only two","Only three","All four of them"],"answer":2,"explanation":"Statements 1, 2 and 4 are correct (the motion rests on Article 75(3) and the Lok Sabha's rules). It is moved against the whole Council of Ministers; a censure motion, which must state reasons, can target an individual minister.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-president-pm-206","question":"The Lok Sabha stands dissolved while the Rajya Sabha is in session. Can the President promulgate an ordinance under Article 123?","options":["No, because the Rajya Sabha can legislate in the absence of the Lok Sabha","Yes, because the bar applies only when both Houses are in session","No, because ordinances cannot be issued while any House of Parliament is dissolved","Yes, but only with the prior approval of the Rajya Sabha"],"answer":1,"explanation":"Article 123 allows an ordinance ‘except when both Houses of Parliament are in session’. With the Lok Sabha dissolved, both Houses are not in session, so the power is available.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-president-pm-207","question":"Parliament reassembles after an ordinance is promulgated. Two weeks later the Lok Sabha alone passes a resolution disapproving it; the Rajya Sabha passes no such resolution. What is the effect on the ordinance?","options":["It ceases to operate as soon as the Lok Sabha passes the resolution","It ceases to operate, since a Lok Sabha resolution binds both Houses","It continues in force until the end of the session in which it was laid","It survives until six weeks after reassembly unless an Act replaces it"],"answer":3,"explanation":"Under Article 123(2)(a), an ordinance ends early only when resolutions disapproving it are passed by both Houses, upon the passing of the second. Otherwise it lapses six weeks after Parliament reassembles.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-president-pm-208","question":"If the Lok Sabha adopts an amendment that defeats the motion of thanks on the President's address, it is treated as:","options":["A censure of the President, requiring a reply under Article 86","Defeat of the government, signalling loss of the House's confidence","A request for the President to deliver a fresh address","A procedural lapse with no constitutional consequence for the ministry"],"answer":1,"explanation":"The address is a statement of the government's policy written by the government, so the House rejecting the motion of thanks amounts to a vote against the ministry.","difficulty":"moderate","source":"UPSC Prelims"},
  {"id":"polity-president-pm-209","question":"Match the President with an event during his tenure: A. Fakhruddin Ali Ahmed B. Giani Zail Singh C. R. Venkataraman D. N. Sanjiva Reddy — 1. Proclaimed the 1975 Emergency on internal disturbance 2. Pocket veto of the Indian Post Office (Amendment) Bill 3. Worked with four Prime Ministers during one term 4. Appointed Charan Singh Prime Minister in 1979","options":["A-1, B-2, C-3, D-4","A-1, B-3, C-2, D-4","A-4, B-2, C-3, D-1","A-1, B-2, C-4, D-3"],"answer":0,"explanation":"Venkataraman (1987–92) served with Rajiv Gandhi, V. P. Singh, Chandra Shekhar and Narasimha Rao; Reddy appointed Charan Singh in July 1979.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-president-pm-210","question":"Under Article 239AB, if the President is satisfied that the administration of the National Capital Territory of Delhi cannot be carried on according to Article 239AA, he may:","options":["Proclaim a National Emergency limited to the territory of Delhi","Dissolve the Delhi Assembly and merge Delhi with a neighbouring State","Transfer the powers of the Delhi Assembly to the Lieutenant Governor permanently","Suspend the operation of any provision of Article 239AA or of laws made under it"],"answer":3,"explanation":"Article 239AB is Delhi's counterpart to Article 356: the President may suspend Article 239AA provisions and make incidental provisions for administering the territory.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-president-pm-211","question":"The Cabinet Secretariat functions under the direct charge of the:","options":["President","Prime Minister","Union Home Minister","Minister of Parliamentary Affairs"],"answer":1,"explanation":"The Cabinet Secretariat, headed by the Cabinet Secretary, works directly under the Prime Minister and services the Cabinet and its committees.","difficulty":"moderate","source":"UPSC Prelims"},
  {"id":"polity-president-pm-212","question":"If the Prime Minister is a member of the Rajya Sabha, who acts as Leader of the House in the Lok Sabha?","options":["The Leader of the Opposition, by convention","The Prime Minister himself, though he cannot vote there","The Speaker, who leads the House in the Prime Minister's absence","A minister who is a Lok Sabha member, nominated by the Prime Minister"],"answer":3,"explanation":"The Prime Minister is normally the Leader of the Lok Sabha; when he sits in the Rajya Sabha, he nominates a minister who is a member of the Lok Sabha to lead it.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-president-pm-213","question":"Consider the following statements about the Vice-President: 1. He must be qualified for election as a member of the Rajya Sabha. 2. He must have completed 35 years of age. 3. A Member of Parliament elected Vice-President is deemed to vacate his seat on the date he enters upon office. How many of the above statements are correct?","options":["Only one","Only two","All three","None of them"],"answer":2,"explanation":"Article 66(3) requires 35 years and qualification for the Rajya Sabha (not the Lok Sabha, as for the President), and Article 66(2) vacates any legislative seat on entering office.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-president-pm-214","question":"Assertion (A): A member of the Rajya Sabha can be appointed Prime Minister. Reason (R): Under Article 75(3), the Council of Ministers is collectively responsible only to the Lok Sabha.","options":["Both A and R are true, and R explains A","Both A and R are true, but R does not explain A","A is true, but R is false","A is false, but R is true"],"answer":1,"explanation":"A is true because the Constitution only requires a minister to be a member of either House (Article 75(5)); R is true but, if anything, cuts the other way and does not explain A.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-president-pm-215","question":"Consider the following statements about civil servants of the Union: 1. They hold office during the pleasure of the President. 2. None of them can be dismissed by an authority subordinate to the one that appointed him. 3. A civil servant can never be dismissed without a hearing. Which of the above is/are correct?","options":["1 and 2 only","1 only","2 and 3 only","1, 2 and 3"],"answer":0,"explanation":"Article 310 states the pleasure doctrine and Article 311(1) gives the protection in 2. Statement 3 is wrong because the proviso to Article 311(2) dispenses with a hearing in cases such as conviction on a criminal charge or when holding an inquiry is not reasonably practicable.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-president-pm-216","question":"The Supreme Court declares the election of a sitting President void. What follows under the Constitution?","options":["The outgoing President's predecessor resumes office until a fresh election","The Vice-President acts as President, and an election is held within six months","The Chief Justice of India acts as President until a fresh election","Parliament elects an acting President by a joint sitting of the two Houses"],"answer":1,"explanation":"Articles 62(2) and 65(1) cover a vacancy arising by death, resignation, removal ‘or otherwise’; a voided election creates such a vacancy, which the Vice-President fills until the new President takes office.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-president-pm-217","question":"Which pair of a description of the Prime Minister and the writer who gave it is NOT correctly matched?","options":["Sun around which planets revolve – Ivor Jennings","Central to its formation, its life and its death – H. J. Laski","Keystone of the cabinet arch – H. J. Laski","Primus inter pares (first among equals) – Lord Morley"],"answer":2,"explanation":"‘Keystone of the cabinet arch’ is Lord Morley's description, along with ‘primus inter pares’. Jennings called the PM the sun around which planets revolve, and Laski said he is central to the cabinet's formation, life and death.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-president-pm-218","question":"Which kind of veto does the President of India NOT have over Bills passed by Parliament?","options":["Absolute veto","Suspensive veto","Pocket veto","Qualified veto"],"answer":3,"explanation":"A qualified veto, overridable only by a higher majority, is the US model. The Indian President can withhold assent (absolute), return a Bill once (suspensive) or sit on it (pocket).","difficulty":"moderate","source":"UPSC Prelims"},
  {"id":"polity-president-pm-219","question":"Consider the following statements: 1. The President can promulgate an ordinance only on subjects on which Parliament can make laws. 2. An ordinance is ‘law’ for the purposes of Article 13 and so cannot abridge Fundamental Rights. 3. An ordinance must be laid before both Houses when they reassemble. How many of the above statements are correct?","options":["Only one","Only two","All three","None of them"],"answer":2,"explanation":"Article 123(3) limits ordinances to Parliament's legislative field, Article 13(3) includes ordinances in ‘law’, and Article 123(2)(a) requires them to be laid before both Houses.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-president-pm-220","question":"In which situation is the President's decision NOT dependent on the advice of the Council of Ministers in the ordinary sense?","options":["Promulgating an ordinance during an inter-session recess of Parliament","Choosing a Prime Minister when a general election gives no party a majority","Proclaiming President's Rule in a State on the Governor's report","Appointing the Comptroller and Auditor General of India under Article 148"],"answer":1,"explanation":"In a hung Lok Sabha there is no ministry to advise, so the President must use personal judgement in choosing who can command a majority. The other three are done on ministerial advice.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-president-pm-221","question":"While deciding a mercy petition under Article 72, can the President examine the trial record and reach a view on the evidence different from that of the courts?","options":["No; he is bound by the courts' findings of fact and can consider only fresh grounds","Only after the Supreme Court gives an advisory opinion on the case under Article 143","Yes; he may scrutinise the record afresh, though he acts on ministerial advice","No; only the Governor may examine the evidence in a clemency case under Article 161"],"answer":2,"explanation":"In Kehar Singh (1989) the Court held that the President may scrutinise the evidence and come to a different conclusion; the power operates in a different field from the judicial process, though it is exercised on advice.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-president-pm-222","question":"Which of the following statements about the Vice-President's role as Chairman of the Rajya Sabha is correct?","options":["He is a nominated member of the Rajya Sabha with a full vote","He is an elected member of the Rajya Sabha and can vote in the first instance","He is not a member and has no vote at all, even in a tie","He is not a member of the Rajya Sabha and has only a casting vote"],"answer":3,"explanation":"The Vice-President is ex officio Chairman but not a member of the House, and under Article 100 the presiding officer votes only in case of an equality of votes.","difficulty":"moderate","source":"UPSC Prelims"},
  {"id":"polity-president-pm-223","question":"How many of the following are done by the President? 1. Appointing the Chief Justice of India 2. Appointing the Governor of a State 3. Appointing the Chairman of a State Public Service Commission 4. Removing a member of a State Public Service Commission","options":["Only one","Only two","Only three","All four of them"],"answer":2,"explanation":"The President appoints the CJI (Article 124) and Governors (Article 155) and removes State PSC members (Article 317). The Governor, not the President, appoints the Chairman and members of a State PSC (Article 316).","difficulty":"hard","source":"UPSC Prelims"},
];

export default questions;
